// nome: QuantoLungo
// input: FILE tempfile
// output: long dimfile
// scopo: Trova dimensione in byte di file di input. Dopo l'oprazione imposta
// scopo: puntatore all'inizio del file.
long QuantoLungo(FILE *tempfile)
{
	long  tempdim;

	fseek(tempfile,0,SEEK_END);
	tempdim=ftell(tempfile);
	fseek(tempfile,0,SEEK_SET);
	return tempdim;
}

// compute the absolute distance between two orienting (facing) values
int AbsDiffO(short First, short Second)
{
	
	short SwapValue;
	WORD WordValue;


	if (First > Second) {
		SwapValue = First;
		First = Second;
		Second = SwapValue;
	}

	// check for porblem first value is negative (very little value) and second positive (very higher value)
	if (First < -16384 && Second > 16384) {
		// compute with positive values
		WordValue = (WORD) First;
		return abs(WordValue - Second);
	}

	return abs(First-Second);
}

// receice as input the current Orienting (facing) of some item, and returns same orient changed to be aligned to 
// more closed direction to some of 8 perfect directions (4 hortogonals ad 4 diagonal)
// if TestForceHortogonal == true, it will be forced to choose a hortogonal direction as returned value.
// in *pGap variable will be returned the absolute difference between the source orient and the returned orient
WORD GetAlignedOrient(short Orient, bool TestForceHortogonal, int *pGap)
{
	int MinDiff;

	if (TestForceHortogonal==false) {
		// verify if perfect direction more closed is one on diagonal direction
		// try south-east (ngle) direction
		MinDiff = AbsDiffO(Orient, 0x2000);
		if (MinDiff <= 0x1000) {
			*pGap=MinDiff;
			return 0x2000;
		}

		// try south-west direction
		MinDiff= AbsDiffO(Orient, 0x6000);
		if (MinDiff <= 0x1000) {
			*pGap =MinDiff;
			return 0x6000;
		}


		MinDiff = AbsDiffO(Orient, (short) 0xA000);

		if (MinDiff <= 0x1000) {
			*pGap =MinDiff;
			return 0xA000;
		}

		// try north-east directio

		MinDiff = AbsDiffO(Orient, (short) 0xE000);
		
		if (MinDiff <= 0x1000) {
			*pGap = MinDiff;
			return 0xE000;
		}
	}

	// try with hortogonal directions
	// try with east (ngle)
	MinDiff = AbsDiffO(Orient, 0x0000);
	if (MinDiff <= 0x2000) {
		*pGap = MinDiff;
		return 0x0000;
	}

	// try with south
	MinDiff = AbsDiffO(Orient, 0x4000);
	if (MinDiff <= 0x2000) {
		*pGap = MinDiff;
		return 0x4000;
	}
	// try with west

	MinDiff = AbsDiffO(Orient, (short) 0x8000);
	

	if (MinDiff <= 0x2000) {
		*pGap = MinDiff;
		return 0x8000;
	}

	// try with north

	MinDiff = AbsDiffO(Orient, (short) 0xc000);
	
	if (MinDiff <= 0x2000) {
		*pGap = MinDiff;
		return 0xc000;
	}
	// it's not possible reaching this point of the code
	sprintf(BufferLog, "ERROR: no aligned orient found for source orient=0x%X", Orient);
	InviaLog(BufferLog);


	*pGap= 0x7000;
	return 0x0000;

	
}
// verifica se c'e' un box (grigio) che inibisce l'occupazione dei nemici
// resitutisce true se non e' possibile occupare questa casella
// il valore pFloor e' quello restituito da GetFloor
bool IsBoxSettore(Tipo_CollGridTr4 *pFloor) 
{
	// 7FE890h    ;Ptr_VetBoxInfos


	int Indice;

	Indice = (pFloor->BoxZoneIndex >> 4) & 0x7ff;
	// se non c'e' un indice valido vuol dire che siamo in mezzo
	// a un muro, per cui in pratica non si puo' comunque andare
	// in uesto settore

	if (Indice == 0x7ff) return true;
	

	if (GlobTomb4.pAdr->pVetBoxZones[Indice].OverlapIndex & 0x8000) return true;

	return false;

}


