// restituisce un numero casuale compreso tra 0 e Massimo-1
int Casuale(int Massimo)
{
	int Numero;



	Numero = rand();
	if (Numero >= Massimo) {
		Numero = Numero % Massimo;
	}
		
	return Numero;

}
