// riceve puntatore a serie di bytes e li converte tutti con xor 0x7f
// nota: si presume che ultimo valore sia sempre zero
char *DecriptaStringa(BYTE *pSerie)
{
	int i;
	static char MexOut[256];

	i=0;
	while (pSerie[i]) {
		 MexOut[i] = (char) (pSerie[i] ^ 0x7f);
		 i++;
	}
	MexOut[i]=0;
	return MexOut;
}
	


// riceve in input il testo formato dalla linea argomenti
// e restituisce un vettore di int contenenti tutti i diversi
// valori. Mentre in TotArgomenti verra' impostato il numero di
// argomenti
// Argomenti dovrebbe avere un formato come questo:
// "452, $40000, 184, -15"
// se c'e' un errore imposta TestErrore=true
int * GetMultipleArguments(char *Argomenti, int *TotArgomenti, bool* TestErrore)
{
	char **VetArgomenti;
	static int VetNumeri[50];
	static char *VetPointer[50];
	static char BufferHost[512];
	int i;
	


	VetArgomenti = Split(Argomenti,',',TotArgomenti,BufferHost,VetPointer,false);
	*TestErrore=false;
	for (i=0;i<*TotArgomenti;i++) {
		VetNumeri[i] = GetArgNumerico(VetArgomenti[i], TestErrore);
		if (*TestErrore==true) break;
	}
	return VetNumeri;
}
