	case 80:
		// 80:Turn. Turn <#>Animating around the center at North (E)Distance in circular way
		RepeatType=1;

		// se gia' c'era azione ignorare

		for (i=0;i<GlobTomb4.TotProgressiveActions;i++) {
			if (GlobTomb4.VetProgressiveActions[i].ActionType == 
						AZ_H_CIRCULAR_ROTATE && 
				GlobTomb4.VetProgressiveActions[i].ItemIndex == 
						ItemIndex) break;
		}

		if (i < GlobTomb4.TotProgressiveActions) break;
		AggiungiItemMosso(ItemIndex);

		i = CreaNuovaAzioneProgressiva();
		pAzione = &GlobTomb4.VetProgressiveActions[i];

		// calcolare il centro su cui ruotare

		if (pOggetto->OcbCode < 128) {
			ValOrient = 256;
		}else {
			ValOrient = pOggetto->OcbCode;
		}

		pAzione->ActionType = AZ_H_CIRCULAR_ROTATE;
		pAzione->Arg1 = SCRIPT_IGNORE;
		pAzione->ItemIndex = ItemIndex;
		pAzione->VetArgWord[6] = 0x4000;
		pAzione->VetArgWord[7] = ValOrient;

		n = ExtraTimer;
		n *= 1024;
		pAzione->VetArgWord[8] = n;
		pAzione->VetArgWord[9] =0; // no blocco
		// trova coordinata del centro
		CalcolaIncremento(0xc000, &IncX, &IncZ, n);

		pAzione->VetArg[0] = pOggetto->CordX + IncX;
		pAzione->VetArg[1] = pOggetto->CordY;
		pAzione->VetArg[2] = pOggetto->CordZ + IncZ;
		break;
	case 81:
		// 81:Turn. Stop circular turning for <#>Animating item in (E)way
		RepeatType=1;
		for (i=0;i<GlobTomb4.TotProgressiveActions;i++) {
			if (GlobTomb4.VetProgressiveActions[i].ActionType == AZ_H_CIRCULAR_ROTATE && 
				GlobTomb4.VetProgressiveActions[i].ItemIndex == ItemIndex) {
				pAzione = &GlobTomb4.VetProgressiveActions[i];
				

				switch (ExtraTimer) {

				case 1:
					// 1:Immediatly
					pAzione->ActionType=0;
					GestioneCompletedProgActions(AZ_H_CIRCULAR_ROTATE, i);
					break;
				case 2:
					
					// 2:Slow down until stopping

					pAzione->VetArgWord[9] = ExtraTimer;
					break;
				case 3:
					// 3:Stop to next east,west,sud or north of the center
					ValOrient = pAzione->VetArgWord[6];

					if (ValOrient >= 0 && ValOrient < 0x4000) {
						NextOrient=0x4000;

					}
					
					if (ValOrient >= 0x4000 && ValOrient < 0x8000) {
						NextOrient = 0x8000;

					}

					if (ValOrient >= 0x8000 && ValOrient < 0xC000) {
						NextOrient = 0xC000;

					}
					if (ValOrient >= 0xc000) {
						NextOrient = 0x10000;
					}

					// ora calclare quanti incrementi ci vogliono
					pAzione->Arg1 = (WORD) (
						(NextOrient - ValOrient) / 
							pAzione->VetArgWord[7]);
					pAzione->Arg1 ++;


					break;
				case 4:
				case 5:
				case 6:
				case 7:
					ValOrient = pAzione->VetArgWord[6];
					switch (ExtraTimer) {
					case 4:
						// Stop when it reachs NORTH of the center
						NextOrient = 0xc000;
						break;
					case 5:
						// 5:Stop when it reachs SOUTH of the center
						NextOrient = 0x4000;
						break;
					case 6:
						// 6:Stop when it reachs EAST of the center
						NextOrient = 0x10000;
						break;
					case 7:
						// 7:Stop when it reachs WEST of the center
						NextOrient = 0x8000;
						break;

					

					}
					pAzione->Arg1 = (WORD) (
						(NextOrient - ValOrient) / 
							pAzione->VetArgWord[7]);
					pAzione->Arg1 ++;
					break;
				
				case 8:
					// 8:Pause. Stop temporary its movement
					pAzione->Arg1 = SCRIPT_IGNORE-1;
					break;

					
				}
				break;
				

			}
		}
		break;
