// inizializza vettore di conversione tra azione e flipeffect che usano
// itemgroup per eseguire azioni specifiche
void InitRemapItemGroup(void)
{

	short *pVet;
	int i;
	short NumAction;

	pVet = GlobTomb4.BaseItemGroup.VetRemapFlipActions;

	for (i=0;i<256;i++) {
		pVet[i] = -1;
	}

	// ora inserire i valori di conversione rispetto a flipeffect
	// NOTA: potrei avere problemi se il numero di flipeffect e' oltre 255
	NumAction = 29;
	for (i=137;i<=144;i++) {
		pVet[i] = NumAction++;
	}


	pVet[145] = 43;
	pVet[146] = 44;


}

void ShowDatiNemico(void)
{

	StrArmiTr4 *pVetCostantiNemici = (StrArmiTr4*) 0x4AB830;
	StrArmiTr4 *pNem;
	int i;
	FILE *pFile;


	pFile = fopen("ListEnemy.txt","wb");

	for (i=0;i<9;i++) {
		pNem = &pVetCostantiNemici[i];
		fprintf(pFile,"RECORD %d\r\n", i);
		
		fprintf(pFile,"\tArmaSingola.  HMinAngle=%d  HMaxAngle=%d  VMinAngle=%d  VMaxAngle=%d\r\n",
			pNem->ArmaSingleHMinAngle, pNem->ArmaSingleHMaxAngle,
			pNem->ArmaSingleVMinAngle, pNem->ArmaSingleVMaxAngle);

		fprintf(pFile,"\tArmaRight.  HMinAngle=%d  HMaxAngle=%d  VMinAngle=%d  VMaxAngle=%d\r\n",
			pNem->ArmaRightHMinAngle, pNem->ArmaRightHMaxAngle,
			pNem->ArmaRightVMinAngle, pNem->ArmaRightVMaxAngle);

		fprintf(pFile,"\tArmaLeft.  HMinAngle=%d  HMaxAngle=%d  VMinAngle=%d  VMaxAngle=%d\r\n",
			pNem->ArmaLeftHMinAngle, pNem->ArmaLeftHMaxAngle,
			pNem->ArmaLeftVMinAngle, pNem->ArmaLeftVMaxAngle);	
		
	
		fprintf(pFile,"\tDatoArmaEstratta=0x%x  OrientDispersione=%d\r\n",
			pNem->DatoArmaEstratta  , pNem->Random  );

		fprintf(pFile, "\tCordYArma=%d\r\n", pNem->CordYArma);
		fprintf(pFile, "\tDistanceTarget=%d  (0x%X)\r\n",
			pNem->DistanceTarget, pNem->DistanceTarget);

		fprintf(pFile, "\tDannoNormale=%d  TempoRicarica=%d\r\n", 
			pNem->DannoArmaNormale, pNem->TempoRicarica );

		fprintf(pFile, "\tDurataFlash=%d\r\n", pNem->DurateFlash);

		fprintf(pFile, "\tFrameCambioArma=%d\r\n", pNem->FrameCambioArma);

		fprintf(pFile, "\tSuonoSparo=%d\r\n\r\n", pNem->SuonoSparo);

	}
	fclose(pFile);

	// solo per esperimento
	pVetCostantiNemici[1].DannoArmaNormale = 0;

}
// inserisci in globtomb4 tutti i dati standard per barre di progressione
// di tomb4
void InitBarDefault(void)
{
	StrPtrBars *pBar;
	int i;

	for (i=0;i<BAR_CUST_TOT;i++) {
		pBar = &GlobTomb4.VetBarDefault[i];

		switch (i) {
		case BAR_HEALTH:
			pBar->DefColor1 = 0xffff0000;
			pBar->DefColor2 = 0xff000000;

			pBar->pColor1 = (DWORD *) 0x47B5B0;
			pBar->pColor2 = (DWORD *) 0x47B5BA;
			pBar->pSizeX = (int *) 0x47B5C5;
			pBar->pSizeY = (BYTE *) 0x47B5C3;
			break;
		case BAR_DASH:
			pBar->DefColor1 = 0xff00ff00;
			pBar->DefColor2 = 0xff000000;

			pBar->pColor1 = (DWORD *) 0x47B523;
			pBar->pColor2 = (DWORD *) 0x47B528;
			pBar->pSizeX = (int *) 0x47B538;
			pBar->pSizeY = (BYTE *) 0x47B536;
			break;
		case BAR_AIR:
			pBar->DefColor1 = 0xff0000ff;
			pBar->DefColor2 = 0xff000000;

			pBar->pColor1 = (DWORD *) 0x47B565;
			pBar->pColor2 = (DWORD *) 0x47B56D;
			pBar->pSizeX = (int *) 0x47B579;
			pBar->pSizeY = (BYTE *) 0x47B575;
			break;
		case BAR_LOAD_LEVEL:
			pBar->DefColor1 = 0xff9f1f80;
			pBar->DefColor2 = 0xff000000;

			pBar->pColor1 = (DWORD *) 0x47B65A;
			pBar->pColor2 = (DWORD *) 0x47B65F;
			pBar->pSizeX = (int *) 0x47B693;
			pBar->pSizeY = (BYTE *) 0x47B68F;
			break;
		case BAR_COLD:
			pBar->DefColor1 = 0xfff924f1;
			pBar->DefColor2 = 0xff000000;
			break;
		case BAR_DAMAGE:
			pBar->DefColor1 = 0xffF6F923;
			pBar->DefColor2 = 0xff000000;
			break;



		

			

		}

	}


}
// usata solo per debug per verificar ese i vettori state id nella dll
// sono uguali a quelli di tomb5 originali

void ControllaVettori(DWORD *pSrc, DWORD *pDest)
{
	int i;

	for (i=0;i<118;i++) {
		if (pSrc[i] != pDest[i]) {
			break;
		}
	}
}

// controlla se in cartella PIX ci sono immagini in formato standard ma
// di tipo jpg

void VerifyImagesPix(void)
{

	StrListaFiles *VetNomi;
	int TotNomi;

	char NomeExe[256];

	VetNomi = TrovaFiles("pix", "image*.jpg", &TotNomi);
	if (TotNomi == 0) return;
	// nel caso sia gia' presente il file converter.exe in cartella pix
	// avviarlo
	strcpy(NomeExe,"pix\\converter.exe");
	if (EsisteFile(NomeExe)==true) {
		MessageBox(NULL, "WARNING: some image in PIX folder is in jpg format, now the jpg images will be converted in bitmap (.bmp) format", "TRNG Warning",0);
		ShellExecute(NULL, "open",GetFileTrle(NomeExe),"", Dir_Trle, SW_SHOW);
		Sleep(4000);
	}else {
		MessageBox(NULL, "WARNING: some image in PIX folder is in jpg format. You should convert them in .bmp format using the CONVERTER.exe utility otherwise they will be not showed in game", "TRNG Warning",0);
		
	}


}
