// primo controllo per presenza di esistenza di file script.dat english/other.dat
void Controllo1FileMancanti(void)
{
	StrBaseMissing *pLog;
	char *VetLingue[] = {"english.dat", "german.dat", "french.dat", "italian.dat",
		"spanish.dat", "us.dat", "japan.dat", NULL};
	char *VetStandard[] = {"load.bmp", "data\\uklogo.pak", NULL};
	int i;

	pLog = &GlobTomb4.BaseMissing;
	memset(pLog,0, sizeof(StrBaseMissing));


	if (EsisteFile("script.dat")==false) {
		strcat(pLog->MexMissing, "CRITICAL ERROR: Missing \"SCRIPT.DAT\" file\r\n");
		pLog->TestErrori=true;
	}else {
		// lo script.dat c'e'
		pLog->TestScriptPresenti =true;

		// vedere se c'e' almeno un file .dat di lingue
		// prima cercare i file language clasici
		i=0;
		while (VetLingue[i]) {
			if (EsisteFile(VetLingue[i]) == true) break;
			i++;
		}
		if (VetLingue[i] == NULL) {
			pLog->TestAvvisi=true;
			strcat(pLog->MexMissing ,
				"WARNING: not found any standard language.dat (english.dat, german.dat ect)\r\n");

		}
	}

	i=0;
	while (VetStandard[i]) {
		if (EsisteFile(VetStandard[i])==false) {
			pLog->TestErrori=true;
			sprintf(BufferLog,"CRITICAL ERROR: missing \"%s\" file\r\n",
				VetStandard[i]);
			strcat(pLog->MexMissing, BufferLog);
			

		}
		i++;
	}

	
	if (pLog->TestErrori) {
		MessageBox(NULL, pLog->MexMissing, "TRNG Diagnostic", MB_APPLMODAL);
	}

	
}
