// restituisce SOLO gli eventuali arogent della line axcomnadi, saltando il nome del file tra virgolette
char *GetArgCommandLine(void)
{

	char *pLinea;
	int i;

	pLinea = GetCommandLine();
	// ora in pLinea ci sar' il noemr del file .exe attuale *tomb4 tra virgolette

	i=0;

	if (pLinea[i] != '\"') {
		// anomalia, uscire subito
		return pLinea;
	}

	i++;
	while (pLinea[i] != 0 && pLinea[i] != '\"') i++;

	if (pLinea[i] == '\"') i++;

	pLinea = &pLinea[i];
	
	return Trim(pLinea);

}
