// restituise la stringa col nome descrittivo del livello NumeroLivello
char * GetNomeLivelloTomb(int NumeroLivello)
{

	BYTE *pVetIndiciNomiLivello = (BYTE *) 0x7FD1A0;
	WORD ** p2VetIndiciStringhe = (WORD **) 0x7FD154;
	WORD *pVetIndiciStringhe;
	char **p2SerieStringhe = (char **) 0x7FD198;
	char *pSerieStringhe;
	int Indice;
	char *pChar;

	pVetIndiciStringhe = *p2VetIndiciStringhe;
	pSerieStringhe = *p2SerieStringhe;

	Indice = pVetIndiciNomiLivello[NumeroLivello];
	Indice = pVetIndiciStringhe[Indice];
	pChar = &pSerieStringhe[Indice];

	return pChar;

}


