// chiamata nel momento in  cui la libreria viene collegata
// se restituisce false bisogna abortire il programma
bool Inizializza(void)
{
	char BufProductTrngVersion[80];
	bool TestEsito;
	static int VetInventory[] = {
			0xAF, 0xB0, 0xB1, 0xB2, 0xB3, 0xB4, 0xB5, 0xB6, 0xB7, 0xB8, 
			0xB9, 0xBA, 0xBB, 0xBC, 0xBD, 0xBE, 0xBF, 0xC0, 0xC1, 0xC2, 
			0xC3, 0xC4, 0xC5, 0xC6, 0xC7, 0xC8, 0xC9, 0xCA, 0xCB, 0xCC, 
			0xCD, 0xCE, 0xCF, 0xD0, 0xD1, 0xD2, 0xD3, 0xD4, 0xD5, 0xD6, 
			0xD7, 0xD8, 0xD9, 0xDA, 0xDB, 0xDC, 0xDD, 0xDE, 0xDF, 0xE0, 
			0xE1, 0xE2, 0xE3, 0xE4, 0xE5, 0xE6, 0xE7, 0xE8, 0xE9, 0xEA, 
			0xEB, 0xEC, 0xED, 0xEE, 0xEF, 0xF0, 0xF1, 0xF2, 0xF3, 0xF4, 
			0xF5, 0xF6, 0xF8, 0xF9, 0xFA, 0xFB, 0xFC, 0xFD, 0xFE, 0xFF, 
			0x100, 0x101, 0x128, 0x129, 0x12A, 0x12B, 0x12C, 0x12D, 
			0x12E, 0x12F, 0x130, 0x131, 0x15D, 0x15E, 0x15F, 0x160, 0x161, 0x162, 
			0x163, 0x164, 0x165, 0x166, 0x167, 0x169, 0x16A, 0x16B, 0x16C, 
			0x16E, 0x16F, 0x170, 0x171, 0x172, 0x173, 0x174,-1};
	int i;


	char *pChar;

	TestEsito=true;
	strcpy(Dir_Trle,TrovaDirectoryCorrente());
#ifdef LOG_CRYPT
	// cancellare log crypt
	remove("crypt_log.txt");
	StampaInLog("Inizio log: Inizializza()");
#endif
	memset(&GlobTomb4,0,sizeof(StrGlobaliTomb4));
	memset(&BaseGlobMisc, 0, sizeof(StrGlobMisc));
	BaseGlobMisc.VetPauseTracks[0].CD_Track=-1;
	BaseGlobMisc.VetPauseTracks[1].CD_Track=-1;

	LinkGlobTomb4Structures();
	memset(&MyGlobPrivate, 0, sizeof(StrMyGlob));
	BaseAlloc.TotAllocata=0;
	TotAllocata=0;

	TestDebugLog=IsAttivoDebugger();


	srand((DWORD) time(NULL));

	pChar = TrovaVersioneFile("Tomb_NextGeneration.dll", BufProductTrngVersion);

	if (pChar==NULL) {
		MexVersione[0]=0;
	}else {
		strcpy(MexVersione,pChar);
	}
	remove("ng_startup_log.txt");

	GlobTomb4.HardwareB.m_index = -1;
	GlobTomb4.HardwareB.Attivo =false;
	GlobTomb4.pDiagnostica->TestSospendiBreakCond=false;
	GlobTomb4.pAdrDiagnostica = &DefValoreZero;

	BYTE *StartDll;
	StartDll = (BYTE *) &Inizializza;

	// riempie con valori casuali la zona di controllo crypt
	memcpy(&MyGlobPrivate.VetControlloKrypt[0], StartDll,987);





#ifdef DEBUG_ON
	MyGlobPrivate.TestDebugVersione=true;
#else
	MyGlobPrivate.TestDebugVersione=false;
#endif

	// valori validi per qualunque exe chiamante

	for (i=0;VetInventory[i]!=-1;i++) {
		GlobTomb4.VetInventory[i] = VetInventory[i];
	}

	GlobTomb4.VetInventory[i] = -1;

	CalcolaVersione(&GlobTomb4.BaseVersione);

	TestBloccoTRY=0;
	LastErroreLog[0]=0;
	LastErrorDX[0]=0;
	TestAttivatoCrash=false;
	GlobTomb4.TestSetCamera = false;
	// ottenere una cartella temporanea
	sprintf(MyTempFolder, "%s\\Temp_Files", Dir_Trle);
	if (EsisteDirectory(MyTempFolder)==false) {
		CreaDirectory(MyTempFolder);
	}

	sprintf(MyCrashFolder, "%s\\TEMP_LOGs", Dir_Trle);
	if (EsisteDirectory(MyCrashFolder)==false) {
		CreaDirectory(MyCrashFolder);
	}
	// scoprire quale exe e' in funzione
	switch (*pCheckMemoryExe) {
		case 0xc328c483:
			// tomb4
			TipoExe =EXE_TOMB4;

			break;
		case 0xd8b0003:
			TipoExe=EXE_EDITOR;
			// room editor
			
			break;
		case 0x8910247c:
			// tom2pc
			TipoExe=EXE_TOM2PC;
			break;
		case 0xf122e900:
			TipoExe=EXE_TOMB5; // tomb5, usato solo per alcune prove

			break;
		case 0x8110e6c1:
			TipoExe=EXE_TOMB3; // tomb3, usato solo per diagnostica

			break;

		default:

			// MessageBox(NULL,"ERROR: Tomb_NextGeneration.dll cann't recognize current exe file", 
			// 		"Next Generation 1.0",MB_APPLMODAL);			
			return true;
		}

	TotCheckMemory=0;
	LastNGHeader.NWords=0;
	LastNGHeader.Result=0;
	LastNGHeader.pNGArray=NULL;
	LastNGHeader.SizeHeader =0;
	LastNGHeader.StartOffset =0;
	SalvaVettoriRemap.TestAttivo=false;


	// il plugin trng considerarlo caricato per qualunque exe
	InizializzaPluginTrng();
	

	if (TipoExe ==EXE_TOMB4) {
		//TOMB4

		// inizializza indirizzi tomb4 in puntatori variabili e procedure
		// Inizializza valori globali
		InizializzaTomb4();
		// aggiorna i blocchi con tutti i plugin caricati
		
		GlobTomb4.LastTombMexage[0]=0;

		// GlobTomb4.MyPrefTomb.Flags =0;
		TestEsito=StartUpTomb4();
		if (TestEsito) {
			InviaErroreLog("The library has been successfully attached!",0,false);
		}else {
			InviaErroreLog("ERROR: failed the attaching of Tomb_NextGeneration.dll",0,false);
		}

	}


	if (TipoExe==EXE_EDITOR) {
		// ROOM EDITOR 
		StartUpRoomEditor();
		// mantenere sempre alla FINE !!!!
		MyGlobPrivate.TestPatchDinamiche=true;


	}

	if (TipoExe ==EXE_TOM2PC) {

		// tom2pc
		PatchVetBumpMapFlags(); //porta a 0x400 dimensione sound textures
		PatchSizeMemTex_1_4(); // incrementa mem texture da 140000 a 30000
		PatchCmpSizeMemTex_1400(); // controllo su dimensione di mem 1400
		PatchSizeMemTex_5_0(); //aumneta mem 5 Mb fino a 15 Mb
		PatchSizeAllocSpaceTexture(); // aumenta mem a 5MB 
		Patch_PerNomeTr4(); // permette di salvare nome tr4
		patch_PerSoundTableEstesa();
		Patch_PerRemappaTailTriangolo();
		Patch_PerRemappaTailQuad();
		Patch_PerAttivareOutNewRanges();
		Patch_PerSetNewRangeSource();
		Patch_PerSizeTexDefault1();
		Patch_PerSizeTexDefault2();
		Patch_PerOffsetFrammenti1();
		Patch_PerOffsetFrammenti2();
		Patch_PerSizeTabSounds();
		// Patch_PerFindAnimTex();
		Patch_PerBugTriangolo();
		patch_PerSizeDefaultTail();
		patch_PerSampleMissing();
		patch_PerSampleMissing2();
		Patch_PerSprite256x256();
		PatchBaseTextureRoom();
		// patch per metacabinet
		Patch_PerMetaCab1();
		Patch_PerMetaCab2();
		Patch_PerMetaCab3();

		patch_per_FixNextAnimInDispatch();
		InizializzaTom2Pc();

	}



	if (TipoExe ==EXE_TOMB3) {
		// tomb3
		InizializzaTomb3();
		Patch_PerEseguiInGame(); // fatta in tomb5
		Patch_PerInizioLivello();  // fatta in tomb5
		PatchTutteEccezioniTomb3();  // fatta in tomb5
		Patch_PerSalvaTR3Stack2(); // fatta in tomb5
		Patch_PerInizioCicloTomb3();  // fatta in tomb5
		Patch_PerSalvaRobaPalude();
		Patch_PerFineCicloGioco();
		Patch_PerAnalisiFondale(); // temporanea per analisi kayak
		Patch_PerControllaCord(); // temporane aper analisi kayak

	}
	if (TipoExe==EXE_TOMB5) {
		// tomb5
		InizializzaTomb5();
		patch_PerT5InizioCiclo();
		patch_PerT5InizioLivello();
		patch_PerT5EseguiInGame();
		Patch_GestioneEccezioni5();
		Patch_perSalvaStack5();
		Patch_perSalvaStack2_5();
		Patch_perSalvaStack3_5();
		patch_PerStampaStringheTr5();
		patch_PerFineCicloTr5();
		patch_PerInizioLoadLivelloTr5();
		Patch_PerSuoniSFX();
		Patch_PerSalvaSFX();
		Patch_PerTitleDiagnostic();
	}
	return TestEsito;
}
void AnalisiFinaleMemAllocateMine(void)
{
	int i;
	StrMemAllocata *pRecord;

#ifdef DEBUG_ON
	InviaLog("Memory  ID  FREE  Descrizione\r\n");
	InviaLog("--------------------------------------------------------\r\n");

	for (i=0;i<BaseAlloc.TotAllocata;i++) {
		pRecord = &BaseAlloc.VetAllocata[i];

		sprintf(BufferLog, "%X  %d  %d  %s\r\n", 
			pRecord->pBaseMem, pRecord->ThreadId, pRecord->TestFree, pRecord->pDescrizione);
		InviaLog(BufferLog);
	}
	InviaLog("--------------------------------------------------------\r\n");
#endif

	// ora liberare comunque tutto
	for (i=0;i<BaseAlloc.TotAllocata;i++) {
		pRecord = &BaseAlloc.VetAllocata[i];
		if (pRecord->pBaseMem) {

			try {
				free(pRecord->pBaseMem);
			} catch(...) {

				sprintf(BufferLog, "Error while I free memory: 0x%X\r\n", pRecord->pBaseMem);
				InviaLog(BufferLog);
			}
		}
	}
			
}
// viene chiamata alla quando la libreria viene staccata (in pratica quando il programma
// finisce
void TerminaProgramma(void)
{
	FILE *pFile;
	int i;
	HINSTANCE *pTombInstance;
	char NomeExe[80];
	static DWORD *pCallBackRedir = (DWORD *) 0x4A6CF8;
	HANDLE HandleProcesso;
	static DWORD *pMem = (DWORD*) 0x4A6D20;
	switch (TipoExe) {
	case EXE_TOMB4:
		// tomb4
		// liberare tutta la memoria rimasta
		AllFreeMine(-1);
		// liberare memoria di errori dgx
		for (i=0;i<GlobTomb4.BaseDgxErrors.TotOld;i++) {

	
			try {
				free(GlobTomb4.BaseDgxErrors.pVetMexOld[i]);
			} catch(...) {


			}
		}
		// eliminare immagini caricate con preload
		for (i=0;i<GlobTomb4.BasePreloadImages.TotPreload;i++) {
			DeleteObject(GlobTomb4.BasePreloadImages.VetPreload[i].hBitMap);
		}
		// ora cancellare il contatore di immagini caricate
		GlobTomb4.BasePreloadImages.TotPreload =0;
		// rimuovere valore di patch per redir di window procedure
		if (*pCallBackRedir) *pCallBackRedir = 0;
		 pTombInstance = (HINSTANCE*) 0x753858;

		 // liberare memoria di tomb4
		// if (MyGlobPrivate.pTomb4Mem != NULL) free(MyGlobPrivate.pTomb4Mem);


		if (GlobTomb4.BaseFMV.WindowBlack) {
			// togleire finestra
			MostraTaskBar();

			DestroyWindow(GlobTomb4.BaseFMV.WindowBlack);
			UnregisterClass(BLACK_FIELD, *pTombInstance);
			GlobTomb4.BaseFMV.WindowBlack = NULL;
		}
		RiattivaAnimWindow();

		if (GlobTomb4.LastTombMexage[0]!=0) {

			// visualizzare adesso messaggio

			pFile=fopen(GetFileCrash("DETECTED CRASH.txt"),"wb");
			fprintf(pFile,"TRNG - Detected Unrecoverable Crash\r\n");
			fprintf(pFile,"%s\r\n", GlobTomb4.LastTombMexage);
			fclose(pFile);
			ShellExecute(NULL,"open",GetFileCrash("DETECTED CRASH.txt"),"",
						Dir_Trle,SW_SHOW);
		}
		if (TipoExe==EXE_TOMB4 && GlobTomb4.TestSetup==false) TerminaDatabase();
		if (GlobTomb4.TestSetup) {
			MessageBoxTomb("New settings have been changed successfully: OK", "Setup Mode");
		}

		break;
	case EXE_EDITOR:

		// room editor
		// salvare preferenze
		TerminaRoomEditor();
		break;
	case EXE_TOM2PC:
		AllFreeMine(-1);
		break;

	}

	// valida per tutti
	for (i=TotAllocata-1;i>=0;i--) {
		if (VetAllocate[i] != NULL) {


			try {
				free(VetAllocate[i]);
			} catch(...) {


			}

		

			VetAllocate[i]=NULL;
		}
	}
	

	if (TestAvviaTomb) {
		sprintf(NomeExe,"%s\\tomb4.exe",Dir_Trle);

		CreaProcesso(NomeExe,"",&HandleProcesso,false);		

	}

	if (TipoExe==1) {
		AnalisiFinaleMemAllocateMine();
	}

}

