// riceve in input il numero assoluto di un sound effect e 
// restituisce la stringa descrittiva del suono.
// per i suoni di tomb4 e' solo un numero ma per gli altri e' un suono
// tr1/2/3/5  o reserved ecc.
char *FormattaSuono(int NumeroSuono)
{
	static char BufSuono[128];

	if (NumeroSuono < 370) {
		// suono standard tomb4
		sprintf(BufSuono,"%d ", NumeroSuono);
		return BufSuono;
	}

	if (NumeroSuono < 500) {
		// Hardcoded
		sprintf(BufSuono, "%d (Hard:%d) ", NumeroSuono, NumeroSuono-370);
		return BufSuono;
	}

	if (NumeroSuono < 525) {
		// sound source
		sprintf(BufSuono,"%d (Src:%d) ", NumeroSuono, NumeroSuono-500);
		return BufSuono;
	}

	if (NumeroSuono < 602) {
		//Animcommands
		sprintf(BufSuono, "%d (Anim:%d) ", NumeroSuono, NumeroSuono-525);
		return BufSuono;
	}

	if (NumeroSuono < 858) {
		// tr1
		sprintf(BufSuono, "%d (Tr1:%d) ", NumeroSuono, NumeroSuono-602);
		return BufSuono;
	}

	if (NumeroSuono < 1228) {
		// tr2
		sprintf(BufSuono, "%d (Tr2:%d) ", NumeroSuono, NumeroSuono-858);
		return BufSuono;
	}

	if (NumeroSuono < 1598) {
		// tr3
		sprintf(BufSuono, "%d (Tr3:%d) ", NumeroSuono, NumeroSuono-1228);
		return BufSuono;
	}

	// se maggiore di tutto deve essere tr5
	sprintf(BufSuono, "%d (Tr5:%d) ", NumeroSuono, NumeroSuono-1598);
	return BufSuono;


}

char *FormattaDescrizioneItem(StrItemTr4 *pItem, DWORD Flags)
{
	static char BufDescrizione[512];
	char BufBound[256];
	int StateId;
	int NextId;
	int NextAnim;
	int IndiceAnim;
	StrBoxCollisione *pBound;
	int MinX, MaxX;
	int MinY, MaxY;
	int MinZ, MaxZ;

	IndiceAnim = pItem->AnimationNow;
	StateId= pItem->StateIdCurrent;
	NextId = pItem->StateIdNext;
	NextAnim = GlobTomb4.pAdr->pVetAnimations[IndiceAnim].NextAnimation;

	// se e' un oggetto diverso da lara bisogna
	// calcolare animazione relativa
	if (pItem->SlotID != 0 && (Flags & FLI_STATIC_ITEM)==0) {
		// trovare prima animazione di questo slot
		IndiceAnim -= GlobTomb4.pAdr->pVetSlot[pItem->SlotID].IndexFirstAnim;
		NextAnim -= GlobTomb4.pAdr->pVetSlot[pItem->SlotID].IndexFirstAnim;
	}
	BufBound[0]='\n';
	BufBound[1]=0;

	if (Flags & FLI_SHOW_BOUND) {
		if (Flags & FLI_STATIC_ITEM) {
			// e' uno static
			pBound= &GlobTomb4.pAdr->pVetEditObjects[pItem->SlotID].CollisionBox;
		}else {
			// e' un moveable
			pBound = GetBoundsAccurate(pItem);
		}
		MinX=pBound->MinX+pItem->CordX;
		MaxX=pBound->MaxX+pItem->CordX;
		MinY=pBound->MinY+pItem->CordY;
		MaxY=pBound->MaxY+pItem->CordY;
		MinZ=pBound->MinZ+pItem->CordZ;
		MaxZ=pBound->MaxZ+pItem->CordZ;
		

		sprintf(BufBound, "\nBound:\n\tMinX=%d\n\tMaxX=%d\n\t\tXSize=%d\n\tHighY=%d\n\tLowY=%d\n\t\tYSize=%d\n\tMinZ=%d\n\tMaxZ=%d\n\t\tZSize=%d\n",
			MinX , MaxX,
			abs(MaxX - MinX),
			MinY , MaxY,
			abs(MinY-MaxY),
			MinZ,  MaxZ,
			abs(MaxZ-MinZ));

	}

	sprintf(BufDescrizione,"Anim=%d (Next=%d)\nStateId=%d (Next=%d)\nHSpeed=%d VSpeed=%d\nRoom=%d Flags=$%x\nCx=%d Cy=%d Cz=%d\nOrienting:\n\tH=%d ($%04X)\n\tV=%d ($%04X)\n\tR=%d ($%04X)%s",
		IndiceAnim, NextAnim, StateId,NextId,
		pItem->SpeedH,
		pItem->SpeedV,
		pItem->Room,
		pItem->FlagsMain,
		pItem->CordX,
		pItem->CordY,
		pItem->CordZ,
		pItem->OrientationH, (WORD) pItem->OrientationH,
		pItem->OrientationV, (WORD) pItem->OrientationV,
		pItem->OrientationT, (WORD) pItem->OrientationT,
		BufBound);
	return BufDescrizione;

}
// restituisce il numero di tick Valore come testo nel 
// formato:  mm:ss:dd
// mm = minuti
// ss = secondi
// dd = decimi

char *FormattaTimer(int Valore) 
{
	static char Buffer[80];
	int Minuti,Secondi;
	float Resto;
	char MiniBuf[60];
	char BufDecimi[60];
	int i;
	int j;
	char MioCar;
	bool TestPreso;


	// ok, ora calcolare tempo
	Minuti = Valore / (FRAME_SECONDO * 60);
	Secondi = Valore % (FRAME_SECONDO * 60);
	
	Resto = (float) Secondi / FRAME_SECONDO;
	sprintf(MiniBuf, "%0.1f", Resto);
	Secondi /= FRAME_SECONDO;

	// ora prendere le due cifre decimali
	j=0;
	i=0;
	TestPreso=false;
	while (MiniBuf[i]) {
		MioCar = MiniBuf[i];
		if (TestPreso) {
			BufDecimi[j++] = MioCar;
			break;
		}else {
			if (MioCar == '.' || MioCar == ',') TestPreso=true;
		}
		i++;
	}

	BufDecimi[j] =0;


	sprintf(Buffer, "%02d:%02d:%s", Minuti, Secondi, BufDecimi);
	return Buffer;


}
// restituisce il valore Valore in hex a 8 cifre ma separate a due a due
// per fare caire meglio i limiti di byte e word
char* FormataHexDiviso(int Valore)
{
	static char Buffer[80];
	char StrHex[40];
	int i,j;
	
	sprintf(StrHex, "%08X", Valore);

	j=0;
	Buffer[j++]='$';

	for (i=0;i<8;i++) {
		if (i != 0) {
			if (i == 4) {
				Buffer[j++] = '-';
			}else {
				if ((i % 2) == 0) {
					Buffer[j++] = '.';
				}
			}
		}
		Buffer[j++] = StrHex[i];
	}

	Buffer[j]=0;
	return Buffer;

		
}
// formatta dati attuali di coordinate detector
void FormattaTaraDetector(char Buffer[])
{
	StrCordDetectors *pDet;
	char BufferTemp[80];
	char *pMexAttivo;
	float *pFloat;
	int *pInt;


	static char *VetNomiDet[] = {"OrgY", "TargetY", 
		"SizeTextX", "SizeTextY",
		"VLineX", "VLineY",
		"GapX", "GapY",
		"TextX", "TextY",
		"VLineY", 
		"OrgX", "OrgY", 
		"TextY"};
	int i;

	pDet = &GlobTomb4.BaseCordDetector;
	pFloat = (float *) &pDet->DetOrgY;
	pInt = &pDet->DetOrgY;

	strcpy(Buffer, "RADAR DETECTOR:\n");

	for (i=0;i<MAX_TARA_ITEMS;i++) {
		
		if (i== 10) {
			strcat(Buffer, "COMPASS DETECTOR:\n");
		}

		if (i==11) {
			strcat(Buffer, "KEYPAD:\n");
		}

		if (i == pDet->IndiceAttivo) {
			pMexAttivo = "----> ";
		}else {
			pMexAttivo = "";
		}
		if (i == 2 || i == 3 || i == 7) {
			sprintf(BufferTemp, "%s%s=%0.2f\n",
				pMexAttivo, VetNomiDet[i], pFloat[i]);
		}else {
			sprintf(BufferTemp, "%s%s=%d\n",
				pMexAttivo, VetNomiDet[i], pInt[i]);
		}
		strcat(Buffer, BufferTemp);
	}
	if (TastoVKPremuto('S')) {
		sprintf(BufferTemp, "--------- ADJUSTMENT DATA (%d x %d) ---------",
			*GlobTomb4.pAdr->pSizeScreenX,
			*GlobTomb4.pAdr->pSizeScreenY);

		InviaLog(BufferTemp);

		InviaLog(Buffer);
		InviaLog("--------- END ADJUSTMENT ----------");
	}




}
// scandisce testo a partire da pTesto[n] e inserisce un '\n' ogni 45 caratteri circa
// per accorciare righe
void AccorciaRiga(char *pTesto, DWORD n)
{
	char *pChar;
	int CarRiga;
	DWORD i;
	DWORD Size;

	if (GlobTomb4.BaseFonts.TestUsaWindowsFont == true) return;
	
	pChar = &pTesto[n];

	CarRiga=0;
	Size= strlen(pChar);

	for (i=0;i<Size;i++) {
		CarRiga++;
		if (CarRiga > 40 && pChar[i] == ' ') {
			pChar[i]='\n';
			CarRiga=0;
		}
	}


}
// aggiorna il numero di demo su disco in GlobTomb4.DemoOnDisk   / GlobTomb4.DemoOnDiskArray
void TrovaDemoNumeri(void)
{

	int i;
	char NomeFile[256];
	int n;

	n=0;

	for (i=1;i<1000;i++) {
		sprintf(NomeFile, "data\\demo%d.pak", i);
		if (EsisteFile(NomeFile)) {
			GlobTomb4.DemoOnDiskArray[n++] = i;
		}
	}

	GlobTomb4.DemoOnDisk=n;


}
bool CaricaDemo(int NumeroDemo)
{
	
	FILE *pFile;
	StrRecording *pRecording;
	char NomeFile[256];

	sprintf(NomeFile, "data\\demo%d.pak", NumeroDemo);

	pFile = fopen(NomeFile, "rb");
	if (pFile==NULL) {
		sprintf(BufferLog, "ERROR: can't load %s file", NomeFile);
		InviaLog(BufferLog);
		return false;
	}

	GlobTomb4.DemoNumberLoaded= NumeroDemo;

	pRecording= GlobTomb4.pBaseDemo;

	fread(&pRecording->Status, 2, 1, pFile);
	fread(&pRecording->Version, 2, 1, pFile);
	fread(&pRecording->DatiLara, sizeof(StrSalvaDatiLara),1, pFile);
	fread(&pRecording->IndexFrame, 4,1, pFile);
	fread(&pRecording->TotFrames, 4, 1, pFile);
	fread(&pRecording->VetFrames[0], 4, pRecording->TotFrames, pFile);

	fclose(pFile);
	
	pRecording->Status = RECF_STOP;
	pRecording->IndexFrame=0;
	return true;

}

void AggiornaListaDemo(void)
{
	FILE *pFile;
	StrRecording *pRecording;
	int i;
	char NomeFile[256];
	int SalvaDemoNow;


	pRecording = GlobTomb4.pBaseDemo;
	SalvaDemoNow=GlobTomb4.DemoNumberLoaded;

	TrovaDemoNumeri();
	// ricreare lista di descrizione
	pFile=fopen("Data//DemoInfos.txt", "wt");
	if (pFile==NULL) return;
	for (i=0;i<GlobTomb4.DemoOnDisk;i++) {
		CaricaDemo(GlobTomb4.DemoOnDiskArray[i]);
		// creare descrizione
		sprintf(BufferLog, "Level=%d Time=%s LaraRoom=%d", 
			pRecording->DatiLara.pLevelNow, 
			FormattaFrames2Time(pRecording->TotFrames, pRecording->IndexFrame ),
			ConvertiTombRoomIndex2NgleIndex(pRecording->DatiLara.Lara.Room));

		fprintf(pFile, "Demo%d.pak  Description: [%s]\r\n", GlobTomb4.DemoOnDiskArray[i], BufferLog);
	}

	fclose(pFile);

	// ricaricare demo
	GlobTomb4.DemoNumberLoaded = SalvaDemoNow;

	sprintf(NomeFile, "data//demo%d.pak", GlobTomb4.DemoNumberLoaded);
	if (EsisteFile(NomeFile)==true) {
		CaricaDemo(GlobTomb4.DemoNumberLoaded);
	}else {

		pRecording->IndexFrame=0;
		pRecording->TotFrames=0;

	}
	


}

void DoDemoBackup(int NumeroDemo)
{
	char NomeFile[256];
	char NomeBackup[256];

	sprintf(NomeFile, "Data//Demo%d.pak", NumeroDemo);
	// salvarlo in file di backup
	sprintf(NomeBackup, "Data//Demo%d.backup", NumeroDemo);
	// cancellare eventuale backup gia' presente
	remove(NomeBackup);
	CopyFile(NomeFile, NomeBackup, FALSE);
}
void EliminaDemoNow(void)
{
	char NomeFile[256];



	DoDemoBackup(GlobTomb4.DemoNumberLoaded);

	sprintf(NomeFile, "Data//Demo%d.pak", GlobTomb4.DemoNumberLoaded);

	remove(NomeFile);
	
	AggiornaListaDemo();


}
// se c'era un backup per questo demo ripristinarlo e trasformare il demo attuale (se presente) in un file di backup
void RestoreDemoFile(void)
{
	char NomeFile[256];
	char NomeBackup[256];
	char NomeTemp[256];
	bool TestRename;

	TestRename=false;

	sprintf(NomeFile, "Data//Demo%d.pak", GlobTomb4.DemoNumberLoaded);
	if (EsisteFile(NomeFile)==true) {
		// devo preservare demo.pak attuiale e poi trasformarlo in file di backup
		TestRename=true;
		sprintf(NomeTemp, "Data//Demo%d.temp", GlobTomb4.DemoNumberLoaded);		
		rename(NomeFile, NomeTemp);

	}
	
	sprintf(NomeBackup, "Data//Demo%d.backup", GlobTomb4.DemoNumberLoaded);

	CopyFile(NomeBackup, NomeFile, FALSE);

	if (TestRename) {
		remove(NomeBackup);
		rename(NomeTemp, NomeBackup);
	}
	AggiornaListaDemo();

}

// chiamato stop dopo registrazione
// salvare dati recording on disk
void SalvaDemo(int NumeroDemo) 
{
	FILE *pFile;
	char NomeFile[256];
	StrRecording *pRecording;
	int SalvaIndexFrame;

	pRecording = GlobTomb4.pBaseDemo;

	
	sprintf(NomeFile, "data\\demo%d.pak", NumeroDemo);

	pFile= fopen(NomeFile, "wb");
	if (pFile==NULL) {
		InviaLog("ERROR: trying to save last demo on disk");
		return;
	}
	pRecording->Status=RECF_STOP;

	fwrite(&pRecording->Status, 2, 1, pFile);
	fwrite(&pRecording->Version,2, 1, pFile);
	fwrite(&pRecording->DatiLara, sizeof(StrSalvaDatiLara),1, pFile);
	fwrite(&pRecording->IndexFrame, 4,1, pFile);
	fwrite(&pRecording->TotFrames, 4, 1, pFile);
	fwrite(&pRecording->VetFrames[0], 4, pRecording->TotFrames, pFile);
	fclose(pFile);
	SalvaIndexFrame=pRecording->IndexFrame;
	AggiornaListaDemo();
	pRecording->IndexFrame=SalvaIndexFrame;


}

// restituisce stringa di testo minuti secondi (mm:ss) corrispondente a totframes
char *FormattaFrames2Time(DWORD TotFrames, DWORD FrameIndex)
{
	static char Buffer[60];
	DWORD TotSecondi;
	DWORD Secondi, Minuti;

	TotSecondi = TotFrames / FRAME_SECONDO;
	Minuti = TotSecondi / 60;
	Secondi = TotSecondi % 60;

	sprintf(Buffer, "%02d:%02d (%d/%d)", Minuti, Secondi, FrameIndex, TotFrames);

	return Buffer;


}

