// aggiorna posizone e orientamento item (che sia stati o moveable) sulla base delle strutture fornite
// i dati originari di coordinate e oriantamento sono in pPos
// note: oggetto ha ragiunto il pavimento restiuisce true
bool AggiornaMoveItem(StrPosAndFacing *pPos, StrProgressiveAction *pAzione, StrMoveParameters *pMove) 
{

	int Orient;
	WORD Direzione;
	int SpeedH;
	short RoomNow;
	int SpeedV;
	void *pFloor;
	int Altezza;
	int DistanzaFatta;
	int DistanzaFinale;
	int Inc;
	int IncX, IncZ;
	bool TestBloccoFloor;
	int OrientNow;
	int OrientFinale;
	int OrientInc;
	int OrientIncNew;

	Orient=pPos->Orient;
	Direzione= pMove->Direzione & DIR_MASK_DIRECTION;

	TestBloccoFloor=false;


	OrientFinale=pAzione->VetArgWord[9];
	OrientInc= pAzione->VetArgShort[10];
	OrientNow= pAzione->VetArgWord[11];

	// se c'e' turning eseguire a meno di non aver gia' raggiunt finalorient
	if (OrientInc && OrientNow != OrientFinale) {
		OrientIncNew = abs(OrientInc);

		if ((OrientNow + OrientIncNew) > OrientFinale) {
			OrientIncNew = OrientFinale- OrientNow;
			
		}

		if (OrientInc < 0) OrientIncNew = -OrientIncNew;		
		
		OrientNow += abs(OrientIncNew);
		
		// ora aggiornare l'orrient nell'oggetto considerando la variazione di segno

		pPos->Orient += OrientIncNew;

		pAzione->VetArgWord[11] = (WORD) OrientNow;
			
	}
	// applicare velocita' ma con calcolo distanza fatta e da raggiungere
	// in modo da non superare il limite
	SpeedH = pAzione->VetArgShort[6];
	SpeedV= pAzione->VetArgShort[3];
	DistanzaFatta = pAzione->VetArgWord[0];
	DistanzaFinale = pMove->Distanza;


	

	// casi diversi se e' dir_up o dir_down
	if (Direzione == DIR_UP || Direzione == DIR_DOWN) {
		// in questo caso la distanza e' verticale
		DistanzaFatta += abs(SpeedH);
		if (DistanzaFatta != DistanzaFinale) {
			if (DistanzaFatta > DistanzaFinale) {
				Inc= abs(DistanzaFinale - pAzione->VetArgWord[0]);
				if (SpeedH> 0) {
					SpeedH = Inc;
				}else {
					SpeedH = -Inc;
				}
				DistanzaFatta = DistanzaFinale;
			}

			pPos->CordY += SpeedH;
		}
	}else {
	
		// altre direzioni dove c''e movimento orizzonale
		if (DistanzaFatta != DistanzaFinale) {
			DistanzaFatta += SpeedH;
			if (DistanzaFatta > DistanzaFinale) {
				SpeedH = DistanzaFinale - pAzione->VetArgWord[0];
				DistanzaFatta=DistanzaFinale;
				// azzerare incredmeneto di speed e velocita' speed
				pAzione->VetArgShort[7]=0;
				pAzione->VetArgShort[6]=0;
			}
		}
	
		// ora aggiornare cordx, cordz sulla base di orient attuale 
		// vedere se in questo tipo di direzione va usato l'orient 
		// inziale  (memorizzato in pAzione->Arg2)
		// oppure l'orient attuale di oggetto pPos
		if (Direzione >= DIR_FORWARD && Direzione <= DIR_RU_TURNING_180) {
			// usare orient attuale di oggetto
			Orient = pPos->Orient;
		}else {
			// usare orient iniziale gia' calcolato
			Orient = pAzione->Arg2;
		}

		// aggiornare coordinate
		if (SpeedH) {
			CalcolaIncremento((WORD) Orient, &IncX, &IncZ, SpeedH);

			pPos->CordX += IncX;
			pPos->CordZ += IncZ;
		}
	}

	pPos->CordY += SpeedV;

	if ((pMove->Flags & FMOV_IGNORE_FLOOR_COLLISION)==0) {
		// se e' sotto floor metterlo a livello di floor
		RoomNow = pPos->Room;

		pFloor= GetFloor(pPos->CordX , pPos->CordY , pPos->CordZ , &RoomNow);
		Altezza=GetHeight(pFloor,pPos->CordX,pPos->CordY,pPos->CordZ);
		if (Altezza==WALL_FLOOR) {
			// in questo caso, bloccare movimento orizzontale
			pPos->CordX -= IncX;
			pPos->CordZ -= IncZ;
			pAzione->VetArgWord[0] = pMove->Distanza;
			pAzione->VetArgShort[6]=0;
			pAzione->VetArgShort[7]=0;
			TestBloccoFloor=true;
		}else {
			
			if (pPos->CordY >= Altezza) {
				pPos->CordY=Altezza;
				TestBloccoFloor=true;
				// azzerare velocita' vspeed attuale
				pAzione->VetArgShort[3]=0;
			}
			if (pAzione->VetArgShort[3] > 0) {
				// siamo in fase di caduta
				// aumentare velocita' se non c'e' blocco di floor
				if (pPos->CordY < Altezza) {
					// incrementare vspeed
					pAzione->VetArgShort[3] += pAzione->VetArgShort[4];
					// vedere di non avere superato il limite
					if (pAzione->VetArgShort[4] > 0) {
						// si sta incrementando
						if (pAzione->VetArgShort[3] > pAzione->VetArgShort[5])  pAzione->VetArgShort[3] = pAzione->VetArgShort[5];
					}else {
						// si sta diminuendo
						if (pAzione->VetArgShort[3] < pAzione->VetArgShort[5]) pAzione->VetArgShort[3] = pAzione->VetArgShort[5];
					}
				}
			}
			if (pAzione->VetArgShort[3] <= 0) {
				// siamo in fase di salita
				// aumentare sempre velocita'
				// incrementare vspeed
				pAzione->VetArgShort[3] += pAzione->VetArgShort[4];
				// vedere di non avere superato il limite
				if (pAzione->VetArgShort[4] > 0) {
					// si sta incrementando
					if (pAzione->VetArgShort[3] > pAzione->VetArgShort[5])  pAzione->VetArgShort[3] = pAzione->VetArgShort[5];
				}else {
					// si sta diminuendo
					if (pAzione->VetArgShort[3] < pAzione->VetArgShort[5]) pAzione->VetArgShort[3] = pAzione->VetArgShort[5];
				}
			}
		

		}

	}
		
	
	pAzione->VetArgWord[0] = (WORD) DistanzaFatta;


	// HSpeed
	if (pAzione->VetArgShort[6] != pAzione->VetArgShort[8]  && DistanzaFatta < DistanzaFinale) {
		pAzione->VetArgShort[6] += pAzione->VetArgShort[7];
		
		// se raggiunta velocita' massima bloccarla a quel valore
		if (pAzione->VetArgShort[7] > 0) {
			// in aumento
			if (pAzione->VetArgShort[6] > pAzione->VetArgShort[8]) {
				pAzione->VetArgShort[6] = pAzione->VetArgShort[8];
			}
		}else {
			// in diminuzione
			if (pAzione->VetArgShort[6] < pAzione->VetArgShort[8]) {
				pAzione->VetArgShort[6] = pAzione->VetArgShort[8];
			}
		}

	}

	return TestBloccoFloor;

}
// usato per variare valori di speed di PARAM_MOVE_ITEM comando basato su percentuale
short VariaPercentuale(short Valore, int Percentuale)
{
	float Parte;
	int Totale;

	if (Percentuale==0) return Valore;


	Parte = (float) Percentuale * (float) Valore;
	Parte /= 100.0f;

	Totale= Float2Int(Parte);

	if (Totale==0 && Valore !=0) {
		Totale=1;
		if (Valore < 0) Totale=-1;
	}

	return (short) Totale;

}
// inizializza valori per frog gravity 
void InitFrogVSpeed(StrProgressiveAction *pAzione, StrMoveParameters *pMove) 
{
	

	WORD VSpeed;
	short StartVSpeed;
	short IncVSpeed;
	short MaxVSpeed;

	VSpeed = (pMove->Speed >> 8) & 0xff;

	
	StartVSpeed= VariaPercentuale(-90, VSpeed);
	IncVSpeed = VariaPercentuale(5, VSpeed);
	MaxVSpeed = VariaPercentuale(64, VSpeed);

	pAzione->VetArgShort[3] = StartVSpeed;
	pAzione->VetArgShort[4] = IncVSpeed;
	pAzione->VetArgShort[5] = MaxVSpeed;


}

void GestioneLoopMoveItem(StrPosAndFacing  *pPos, StrProgressiveAction *pAzione, StrMoveParameters *pMove)
{
	WORD Direzione;
	int i;
	StrItemTr4 *pOggetto;

	// azzera distanza e inverti orient?
	pAzione->VetArgWord[0]=0;
	Direzione = pMove->Direzione & DIR_MASK_DIRECTION;
	// mantenere velocita'  massima e stabile

	pAzione->VetArgShort[7]=0;
	pAzione->VetArgShort[8] = pAzione->VetArgShort[6];
	switch (Direzione) {
	case DIR_UP:
	case DIR_DOWN:

		// lasciare speed max e invertire segno

	
		pAzione->VetArgShort[3] = -pAzione->VetArgShort[3];
		pAzione->VetArgShort[4] = 0;
		pAzione->VetArgShort[5] = pAzione->VetArgShort[3];
		break;


	case DIR_FORWARD:

		// invertire direzione
		// invertire facing di oggetto
		pPos->Orient  -= 0x7fff;
		pAzione->Arg2 -= 0x7fff;


		break;
	case DIR_NORTH:
	case DIR_EAST:
	case DIR_SOUTH:
	case DIR_WEST:
		pAzione->Arg2 -= 0x7fff;
		break;

	case DIR_TURNING_LEFT_90:
	case DIR_TURNING_LEFT_45:
	case DIR_LU_TURNING_180:
	case DIR_TURNING_RIGHT_45:
	case DIR_TURNING_RIGHT_90:
	case DIR_RU_TURNING_180:
		pAzione->VetArgShort[11]=0;

		break;
	case DIR_LARA_FACING:
	case DIR_LEADING_ACTOR_FACING:
	case DIR_DIRECTION_LARA_LEADING_ACTOR:


		pAzione->Arg2 -= 0x7fff;
		break;
	case DIR_HEAD_FOR_LARA:
	case DIR_HEAD_FOR_LEADING_ACTOR:
	case DIR_HEAD_FOR_EXTRA_ACTOR:
		// ricaclolare direzione
		switch (Direzione) {
		case DIR_HEAD_FOR_LARA:
			pOggetto= GlobTomb4.pAdr->pLara;
			break;
		case DIR_HEAD_FOR_LEADING_ACTOR:
			i = GlobTomb4.pBaseCutscene->LeadingActorIndex;
			if (i==-1) {
				InviaLog("ERROR: Index of Leading Actor it has not been set");
				pAzione->ActionType=0;
				return;
			}
			pOggetto = &GlobTomb4.pAdr->pVetItems[i];
			break;
		case DIR_HEAD_FOR_EXTRA_ACTOR:
			i = GlobTomb4.pBaseCutscene->ExtraActorIndex; 
			if (i==-1) {
				InviaLog("ERROR: Index of Extra Actor it has not been set");
				pAzione->ActionType=0;
				return;
			}
			pOggetto = &GlobTomb4.pAdr->pVetItems[i];
			break;						
		}

		pAzione->Arg2 = mGetAngle(pPos->CordX, pPos->CordZ, pOggetto->CordX, pOggetto->CordZ);
		pAzione->Arg2 += 0x4000;
		if (pMove->Direzione  & DIR_INVERT_DIRECTION) pAzione->Arg2 += 0x7fff;
		break;
	
		
	}

	if (pMove->Flags & FMOV_FROG_JUMP_GRAVITY) {
		// inizializzare nuovamente dati su velocita'
		InitFrogVSpeed(pAzione, pMove);
	}


}
