// controlla se lara nel corrente blocco e' nella striscia numero NStrip
// dove 0 = la striscia attaccata al bordo verso cui guarda
// e 3 = e' la quarta striscia sul bordo alle sue spalle
// nota: imposta in struttura globa GlobTomb4.EnvPosition
// l'orientamento e le coordinate ideali richieste dai flag
// in modo da permettere in seguito di aggiorarne
bool ControllaENVFlags(WORD EnvFlags)
{
	WORD Orient;
	int Differenza;
	DWORD CordX,CordZ;
	DWORD GapX, GapZ;
	DWORD Striscia;
	WORD TipoStriscia;
	DWORD IdealX,IdealZ;
	int IdealY;
	int  CordY;
	bool TestZona;


	
	if (EnvFlags == 0) return true;
	
	TestZona=false;

	CordX = GlobTomb4.pAdr->pLara->CordX & 0x3ff;
	CordZ = GlobTomb4.pAdr->pLara->CordZ & 0x3ff;
	IdealX = CordX;
	IdealZ = CordZ;
	IdealY = GlobTomb4.pAdr->pLara->CordY & 0x3ff;


	GapX = CordX / 342;
	GapZ = CordZ / 342;

	if (EnvFlags & ENV_POS_IN_THE_MIDDLE) {
		TestZona=true;
		// vedere che sia in porzione centrale
		if (GapX != 1 || GapZ != 1) return false;
	}
	

	Orient = GetAlignedOrient(GlobTomb4.pAdr->pLara->OrientationH, true, &Differenza);
	
	// se c'e' condizione di posizione ortogonale
	// scartare subito se lo scarto da orientamento e' maggiore
	// di 0xa00
	if (EnvFlags & ENV_POS_HORTOGONAL) {
		if (Differenza > 0xA00) return false;

		GlobTomb4.EnvPosition.Orient = Orient;
	}else {
		GlobTomb4.EnvPosition.Orient = GlobTomb4.pAdr->pLara->OrientationH;
	}

	// ora controllare la posizione delle striscie 
	TipoStriscia = EnvFlags & 0xE300;

	
	if (TipoStriscia) {
		TestZona=true;
		// sulla base dell'orientamento
		switch (Orient) {
		case 0x0000:
			// rivolto a est nel ngle
			// quindi devo analizzare GapZ
			Striscia = 2 - GapZ;
			IdealZ = 341 * GapZ + 171;
			if ((EnvFlags & ENV_POS_CENTRAL) != 0) {
				if (GapX != 1) return false;
				IdealX = 341 + 171;
			}

			break;
		case 0x8000:
			// rivolto a ovest
			Striscia = GapZ;
			IdealZ = 341 * GapZ + 171;

			if ((EnvFlags & ENV_POS_CENTRAL) != 0) {
				if (GapX != 1) return false;
				IdealX = 341 + 171;
			}

			break;
		case 0x4000:
			// rivolto a sud
			Striscia = 2 - GapX;
			IdealX = 341 * GapX + 171;

			if ((EnvFlags & ENV_POS_CENTRAL) != 0) {
				if (GapZ != 1) return false;
				IdealZ = 341 + 171;
			}

			break;
		case 0xC000:
			// rivolto a nord
			Striscia = GapX;
			IdealX = 341 * GapX + 171;

			if ((EnvFlags & ENV_POS_CENTRAL) != 0) {
				if (GapZ != 1) return false;
				IdealZ = 341 + 171;
			}
			break;
		}


		// ora applicre condizioni
		switch (TipoStriscia) {
		case ENV_POS_STRIP_1:
			if (Striscia != 0) return false;
			break;
		case ENV_POS_STRIP_2:
			if (Striscia != 1) return false;
			break;
		case ENV_POS_STRIP_3:
			if (Striscia != 2) return false;
			break;
		case ENV_POS_RIGHT_CORNER:
			if (Striscia) return false;

			switch (Orient) {
			case 0x0000:
				// verso est
				if (CordX < 0x322) return false;
				IdealX = 0x31f;
				break;
			case 0x4000:
				// verso sud
				if (CordZ > 0xde) return false;
				IdealZ = 0xde;
				break;
			case 0x8000:
				// verso ovest
				if (CordX > 0xde) return false;
				IdealX = 0xde;
				break;
			case 0xC000:
				// verso nord
				if (CordZ < 0x322) return false;
				IdealZ = 0x322;
				break;
			}

			break;

		case ENV_POS_LEFT_CORNER:

			if (Striscia) return false;

			switch (Orient) {
			case 0x0000:
				// verso est
				if (CordX > 0xde) return false;
				IdealX = 0xde;
				break;
			case 0x4000:
				// verso sud
				if (CordZ < 0x322) return false;
				IdealZ = 0x322;
				break;
			case 0x8000:
				// verso ovest
				if (CordX < 0x322) return false;
				IdealX = 0x322;
				break;
			case 0xC000:
				// verso nord
				if (CordZ > 0xde) return false;
				IdealZ = 0xde;
				break;
			}

			break;
		}
	}

	if (EnvFlags & ENV_POS_IN_THE_MIDDLE) {
		TestZona=true;
		// impostare la posizione ideale per centro
		IdealX = 512;
		IdealZ = 512;
		
		switch (Orient) {
		case 0:
			// guarda verso est
			IdealZ -= 128;
			break;
		case 0x8000:
			// guarda verso ovest
			IdealZ += 128;
			break;
		case 0x4000:
			// guarda verso sud
			IdealX -= 128;
			break;
		case 0xC000:
			// guarda verso nord
			IdealX += 128;
			break;
		}
	}

	if (TestZona) {

		// salvare i valori modificati
		CordX = GlobTomb4.pAdr->pLara->CordX & ~1023;
		CordY = GlobTomb4.pAdr->pLara->CordY & ~1023;
		CordZ = GlobTomb4.pAdr->pLara->CordZ & ~1023;
		
		GlobTomb4.EnvPosition.CordX = CordX | IdealX;
		GlobTomb4.EnvPosition.CordY = CordY | IdealY;
		GlobTomb4.EnvPosition.CordZ = CordZ | IdealZ;
	}else {

		GlobTomb4.EnvPosition.CordX = GlobTomb4.pAdr->pLara->CordX;
		GlobTomb4.EnvPosition.CordY = GlobTomb4.pAdr->pLara->CordY;
		GlobTomb4.EnvPosition.CordZ = GlobTomb4.pAdr->pLara->CordZ;		
	}

	return true;

}
// verifica se ogggetto pOggetto, e' (approssimativamente come y)
// sopra uno qualunque degli oggetti tipo pedana mobile.
bool IsSopraPedana(StrItemTr4 *pOggetto, int *pCordY) 
{

	DWORD GridX,GridZ;
	int BaseY;
	DWORD OggX, OggZ;
	int i;
	WORD Slot;
	StrItemTr4 *pItem;
	int DifY;
	int CordY;



	BaseY = pOggetto->CordY;
	GridX = pOggetto->CordX >> 10;
	GridZ = pOggetto->CordZ >> 10;

	for (i=0;i<GlobTomb4.TotPedane;i++) {

		pItem = GlobTomb4.VetPlatforms[i];


		Slot = pItem->SlotID;

		switch (Slot) {
		case 149:  // one block platform
		case 151: // raising block1
		case 152: // raising block2
		case 153: // EXPANDING_PLATFORM
			// controllo su singolo settore griglia
			OggX = pItem->CordX >> 10;
			OggZ = pItem->CordZ >> 10;

			if (OggX == GridX && OggZ == GridZ) {
				// griglia e' giusta, ora fare calcolo approssimmativo
				// per cord y
				CordY = TrovaCordYRais(pItem, pOggetto->CordY );
				DifY = abs(BaseY - CordY);
				if (DifY < 128) {
					*pCordY = CordY;

					return true;
				}
			}
			break;
		case 150:
			// TWOBLOCK_PLATFORM
			// calcolo particolare per twoblock platform
			// usare funzione specifica
			CordY = TrovaCordYRais(pItem, pOggetto->CordY );
			DifY = abs(BaseY - CordY);
			if (DifY < 128) {
				if (OnTwoBlockPlatform(pItem, 
					pOggetto->CordX, pOggetto->CordZ) == true) {
					*pCordY=CordY;	

					return true;
				}
				
			}
			break;
		}

	}

	return false;
}
// calcola incrementi per arrivare ad una certa distanza
// nella direzione Orientamento
void CalcolaIncremento(WORD Orientamento, int *pIncX, int *pIncZ, int Distanza)
{
	int IncX, IncZ;
	int Indice;
	short * pMatriceOrientamento = (short *) 0x4B34D0;

	if (Distanza == 0) {
		*pIncX = 0;
		*pIncZ = 0;
		return;
	}

	Indice = Orientamento >> 3;
	Indice &= 0x1FFE;
	
	IncX = pMatriceOrientamento[Indice] <<	12;
	IncZ = pMatriceOrientamento[Indice+1] << 12;
	IncX = IncX >> 14;
	IncZ = IncZ >> 14;
	// modificarli sulla base di distanza richiesta
	if (Distanza != 1024) {
		IncX = ProporzioneDistanza(IncX, Distanza);
		IncZ = ProporzioneDistanza(IncZ, Distanza);
	}

	*pIncX = IncX;
	*pIncZ = IncZ;


}
// restituisce l'intera word per climb trovata
// in settore di pFloor (valore ottenuto da funzione GetFloor()
// se non c'e' climb restituisce 0
WORD TrovaValoriClimb(WORD *pFloor)
{
	int Indice;
	WORD **ptr2_FloorData = (WORD **) 0x533948;
	WORD *ptr_FloorData;
	WORD Valore;

	// indice data floor
	Indice = pFloor[0];
	if (Indice == 0) return 0;

	ptr_FloorData = *ptr2_FloorData;
	Valore = ptr_FloorData[Indice];

	if ((Valore & 0x1f) == 6) {
		// valore climb)
		return Valore;
	}
	if (Valore & 0x8000) return 0;
	Indice++;
	// provare il successivo
	Valore = ptr_FloorData[Indice];
	if ((Valore & 0x1f) == 6) return Valore;

	return 0;

}
// se lara e' di tipo monkey questa funzione restringe la prima
// o ultima striscia in modo da renderla piu' vicino al bordo 
// possibile
// se restituisce true allora lara e' nella micro striscia giusta
// altrimenti restituisce false
bool TestPerBordoMonkey(DWORD CordX, DWORD CordZ, WORD EnvFlag, WORD Orient)
{

	WORD StateId;
	DWORD GapX;
	DWORD GapZ;
	DWORD Distanza;

	StateId = GlobTomb4.pAdr->pLara->StateIdCurrent;
	// non fare microstrisca se lara e' diversa da monkey
	if (StateId < 75 || StateId > 79) return true;
	if ((EnvFlag & (ENV_POS_STRIP_3 + ENV_POS_STRIP_1))==0) return true;


	GapX = CordX & 0x3ff;
	GapZ = CordZ & 0x3ff;


	Distanza = 100;
	
	if (EnvFlag & ENV_POS_STRIP_1) {
		// lara ha davanti il bordo

		switch (Orient) {
		case 0x0000:
			// verso est
			if (GapZ >= (1024-Distanza)) return true;
			break;
		case 0x8000:
			// verso ovest
			if (GapZ < Distanza) return true;
			break;
		case 0x4000:
			// verso sud
			if (GapX >= (1024 - Distanza)) return true;
			break;
		case 0xC000:
			// cverso nord
			if (GapX < Distanza) return true;
			break;
		}
	}
	if (EnvFlag & ENV_POS_STRIP_3) {
		// Lara ha alle spalle il bordo, quindi e' tutto invertito
		switch (Orient) {
		case 0x0000:
			// verso est
			if (GapZ < Distanza) return true;
			break;
		case 0x8000:
			// verso ovest
			if (GapZ >= (1024- Distanza)) return true;
			break;
		case 0x4000:
			// verso sud
			if (GapX < Distanza) return true;
			break;
		case 0xC000:
			// cverso nord
			if (GapX >= (1024-Distanza)) return true;
			break;
		}
	}
	
	return false;
}
// restituisce il nuovo valore per incremeto rapportato
// alla distanza richiesta.
// ossia: se la distanza richiesta fosse esattamente un settore (0x400)
// allora incrmeento resterebbe uguale
// se invece distanza fosse due settori 0x800 allora incremento 
// sarebbe raddoppiato
int ProporzioneDistanza(int Incremento, int Distanza)
{
	float Temp;
	float Result;

	Temp = (float) Distanza / 1024;
	Result = (float) Incremento * Temp;

	return (int) Result;

}
