// salva dati per animazione di lara in variabile globali
void BackupLara(StrBackupLara *pBack, StrItemTr4 *pOggetto)
{
	DWORD *pCopiaOrientamento = (DWORD *)  0x80DF64; //   ;ZonaSave_FB_CopiaOrientamento

	pBack->CopiaOrientamento = *pCopiaOrientamento;
	pBack->AnimationNow  = pOggetto->AnimationNow;
	pBack->FrameNow  = pOggetto->FrameNow;
	pBack->StateIdCurrent  =pOggetto->StateIdCurrent;
	pBack->StateIdNext  = pOggetto->StateIdNext;
	pBack->LaraRoom = pOggetto->Room;
	pBack->LaraX = pOggetto->CordX;
	pBack->LaraY = pOggetto->CordY;
	pBack->LaraZ = pOggetto->CordZ;
	pBack->Orient = pOggetto->OrientationH;
	pBack->SpeedH = pOggetto->SpeedH;
	pBack->SpeedV = pOggetto->SpeedV;

}

void RestoreLara(StrBackupLara *pBack, StrItemTr4 *pOggetto)
{

	DWORD *pCopiaOrientamento = (DWORD *)  0x80DF64; //   ;ZonaSave_FB_CopiaOrientamento

	*pCopiaOrientamento = pBack->CopiaOrientamento;

	pOggetto->AnimationNow = pBack->AnimationNow;
	pOggetto->FrameNow =pBack->FrameNow;
	pOggetto->StateIdCurrent = pBack->StateIdCurrent;
	pOggetto->StateIdNext =	pBack->StateIdNext;
	pOggetto->Room = pBack->LaraRoom;
	pOggetto->CordX = pBack->LaraX;
	pOggetto->CordY = pBack->LaraY;
	pOggetto->CordZ = pBack->LaraZ;
	pOggetto->OrientationH= pBack->Orient;
	pOggetto->SpeedH=pBack->SpeedH;
	pOggetto->SpeedV = pBack->SpeedV;


}



// verifica se lara puo' muoversi a destra o a sinistra
// valore di default e' 140 per distanza
bool PuoClimbLaterale(int Distanza, bool TestDestra)
{
	int MinY,MaxY,MaxX,MinX;
	int Valore;
	WORD *pCopiaOrientamento = (WORD*) 0x80DF64; // ZonaSave_FB_CopiaOrientamento:
	WORD Orient;
	bool Esito;

	WORD SalvaTastiInput;


	if (LaraCheckForLetGo(GlobTomb4.pAdr->pLara,
			GlobTomb4.pAdr->pCollisionLara) != 0) return false;

	GlobTomb4.pAdr->pCollisionLara->FrameNowOld  = 
		GlobTomb4.pAdr->pLara->FrameNow;

	MinY = GlobTomb4.pAdr->pCollisionLara->LaraSizeX;
	Orient = GlobTomb4.pAdr->pLara->OrientationH;
	SalvaTastiInput = *GlobTomb4.pAdr->pInputGameCommands;
	if (TestDestra == true) {

		MaxY = MinY + Distanza;
		Orient += 0x4000;
		*GlobTomb4.pAdr->pInputGameCommands = 0x48;

	}else {
		// sinistra
		MaxY = -Distanza - MinY;
		Orient -= 0x4000;
		*GlobTomb4.pAdr->pInputGameCommands= 0x44;

	}
	MinX = -512;
	MaxX= 512;


	*pCopiaOrientamento = Orient;

	Esito= LaraTestClimbPos(GlobTomb4.pAdr->pLara, 
			MinY, MaxY, MinX, MaxX, &Valore);
	*GlobTomb4.pAdr->pInputGameCommands=SalvaTastiInput;



	return Esito;

}
// verifica se lara puo' spostarsi ulteriormente a destra o sinistra
bool PossibileHangMovimento(WORD OrientAlign, bool TestDestra, short Distanza)
{

	int Orient;
	bool Esito;
	DWORD SalvaX, SalvaZ;

	if (Distanza) {
		SalvaX = GlobTomb4.pAdr->pLara->CordX;
		SalvaZ = GlobTomb4.pAdr->pLara->CordZ;

		// fare piccolo assestamento
		if (TestDestra==false) {
			// movimento a sinistra

			switch(OrientAlign) {
			case 0:
				// guarda verso est
				// moviemento x
				SommaControllata(&GlobTomb4.pAdr->pLara->CordX,
						-Distanza,0x10);
				break;
			case 0x4000:
				// guarda verso sud
				SommaControllata(&GlobTomb4.pAdr->pLara->CordZ, 
						Distanza,0x10);
				break;
			case 0x8000:
				// guarda verso est
				SommaControllata(&GlobTomb4.pAdr->pLara->CordX , 
						Distanza,0x10);
				break;
			case 0xc000:
				// guarda verso nord
				SommaControllata(&GlobTomb4.pAdr->pLara->CordZ, 
						-Distanza,0x10);
				break;
			}
		}else {
			// a destra
			switch(OrientAlign) {
			case 0x000:
				// guarda verso nord
				// moviemento x
				SommaControllata(&GlobTomb4.pAdr->pLara->CordX, 
						Distanza,0x10);
				break;
			case 0x4000:
				// guarda verso sud
				SommaControllata(&GlobTomb4.pAdr->pLara->CordZ, 
						-Distanza,0x10);
				break;
			case 0x8000:
				// guarda verso est
				SommaControllata(&GlobTomb4.pAdr->pLara->CordX,
						-Distanza,0x10);
				break;
			case 0xc000:
				// guarda verso nord
				SommaControllata(&GlobTomb4.pAdr->pLara->CordZ, 
						Distanza,0x10);
				break;
			}
		
		}

	}

	if (TestDestra==false) 
		Orient = -16384;
	else
		Orient =0x4000;
	
	Esito= CanLaraHangSideways(GlobTomb4.pAdr->pLara,
			GlobTomb4.pAdr->pCollisionLara, Orient);

	if (Distanza) {
		// ripristinare cordx e cordz
		GlobTomb4.pAdr->pLara->CordX = SalvaX;
		GlobTomb4.pAdr->pLara->CordZ = SalvaZ;
	}
	return Esito;

}
// verifica se lara e' in posizione prevista da position rispetto ad item IndiceOggetto
bool VerificaTestPosition(StrTestPositionCmd *pPosition, int IndiceOggetto)
{

	StrItemTr4 *pItem;
	short VetOrientH[6];
	int TotOrientH;
	int IncX, IncZ;
	int Distanza;
	short OrientOriginale;
	int i;
	short Temp;
	bool TestResult;
	short DifOrient;
	StrItemTr4 *pLara;
	int IdPosition;
	StrTestPosition TempTestPosition;
	StrTestPosition *pTestPos;
	IdPosition = pPosition->IdTestPosition;
	
	pItem = &GlobTomb4.pAdr->pVetItems[IndiceOggetto];
	pLara = GlobTomb4.pAdr->pLara;

	if ((pPosition->Flags & TPOS_TEST_ITEM_INDEX)==0 &&  
		pItem->SlotID != pPosition->Slot ) return false;

	pTestPos = &pPosition->DatiPosition;

	if (pPosition->Flags & TPOS_SELF_FIXING) {
		// se la differenza ideale id hfacing e' intorno a 0x8000, esegui un aggiustamento
		// prima di fare il controllo
		if (pTestPos->Orienting.OrientHMax < pTestPos->Orienting.OrientHMin ) {
			// aggiungere temporaneamente 0x4000 a entrambi
			pItem->OrientationH += 0x7fff;
			TempTestPosition = *pTestPos;
			TempTestPosition.Orienting.OrientHMax -= 0x7fff;
			TempTestPosition.Orienting.OrientHMin -= 0x7fff;
			TestResult=TestLaraPosition(&TempTestPosition,	pItem, pLara);
			// ripristinare valori
			pItem->OrientationH -= 0x7fff;

			return TestResult;
		}
	}
	if (pPosition->Flags & TPOS_TURN_FACING_90) {
		// fare ivnersione
		TempTestPosition = pPosition->DatiPosition;

		pTestPos= &TempTestPosition;

		pTestPos->Distance.MinX = pPosition->DatiPosition.Distance.MinZ;
		pTestPos->Distance.MaxX = pPosition->DatiPosition.Distance.MaxZ;

		pTestPos->Distance.MinZ = - pPosition->DatiPosition.Distance.MaxX;
		pTestPos->Distance.MaxZ = - pPosition->DatiPosition.Distance.MinX;
	}

	// ora effettuare calcolo con rotazione
	// ossia a seconda di flag calcola tutti gli orient simulati 
	// con cui modificare l'orientamento di item temporaneamente
	OrientOriginale = pItem->OrientationH;
	
	TotOrientH =0;
	VetOrientH[TotOrientH++] = OrientOriginale;

	if (pPosition->Flags & TPOS_DOUBLE_HORIENT) {
		// aggiungere anche inverso
		VetOrientH[TotOrientH++] = OrientOriginale + 0x8000;
	}


	if (pPosition->Flags & TPOS_FOUR_HORIENT) {
		// aggiungere altri 3 orientamento aumentando sempre 0x4000
		Temp = OrientOriginale;
		for (i=0;i<3;i++) {
			Temp += 0x4000;
			VetOrientH[TotOrientH++] = Temp;
		}
	}
	if (pPosition->Flags & TPOS_ROUND_HORIENT) {
		// farlo manualmente
		Distanza = pLara->CordY - pItem->CordY;
		if (Distanza < pPosition->DatiPosition.Distance.MinY ||
			Distanza > pPosition->DatiPosition.Distance.MaxY) return false;

		// vedere se distanza e' ok, usare solo min e max z distance

		Distanza = DistanzaPrecisaXZ(pLara->CordX, pLara->CordZ, pItem->CordX, pItem->CordZ);
		if (Distanza < pPosition->DatiPosition.Distance.MinZ ||
			Distanza > pPosition->DatiPosition.Distance.MaxZ) return false;
		// trovare orienting idale di lara verso oggetto:
		OrientOriginale=mGetAngle(pLara->CordX, pLara->CordZ, pItem->CordX, pItem->CordZ);
		OrientOriginale+= 0x4000;
		GlobTomb4.TestPosOrientIdeal = OrientOriginale;
		// ora calcolare differenza rispetto a dove lara guarda
		DifOrient = OrientOriginale - pLara->OrientationH;

		if (DifOrient < pPosition->DatiPosition.Orienting.OrientHMin  ||
			DifOrient > pPosition->DatiPosition.Orienting.OrientHMax) return false;
		
		GlobTomb4.TestPosOrientIdeal = OrientOriginale;
		// ora calcolare posizione ideale di lara
		OrientOriginale += 0x7fff;
		Distanza = (pPosition->DatiPosition.Distance.MaxX + pPosition->DatiPosition.Distance.MinX) >> 1;
		CalcolaIncremento(OrientOriginale, &IncX, &IncZ, Distanza);
		GlobTomb4.TestPosXIdeal = pItem->CordX + IncX;
		GlobTomb4.TestPosZIdeal = pItem->CordZ + IncZ;


	}else {


		for (i=0;i<TotOrientH;i++) {
			pItem->OrientationH = VetOrientH[i];
			if (TestLaraPosition(pTestPos,	pItem, pLara)==true) break;
		}
		pItem->OrientationH = OrientOriginale;
		if (i == TotOrientH) return false;

		// trovato! salvare the orient ideale
		GlobTomb4.TestPosOrientIdeal = VetOrientH[i];
	}

	// trovato l'oggetto
	// qui andrebe salvato in variabile globale
	// per poterlo usare come oggetto di riferimento
	GlobTomb4.IndiceItemCondizione = IndiceOggetto;
	// salvare Id di ultimo testposition usato
	GlobTomb4.TestPosLastID = IdPosition;
	GlobTomb4.TestPosLastItem = pItem;
	GlobTomb4.TestPosLastIndex = IndiceOggetto;

	return true;
}
