// modifica orientamento verticale in modo da seguire la stessa
// inclinazione del settore dove si trova
// calcolato solo lungo l'asse  di rotazione
void AllineaAFloor(StrItemTr4 *pItem) 
{
	void *pFloor;
	short Room;
	int DifX;
	int DifZ;
	int Scarto;
	WORD Orient;

	Room = pItem->Room;

	pFloor = GetFloor(pItem->CordX, pItem->CordY, pItem->CordZ, &Room);
	GetHeight(pFloor, pItem->CordX, pItem->CordY, pItem->CordZ);


	if (*GlobTomb4.pAdr->pInclinationType != 0) {
		DifX = *GlobTomb4.pAdr->pInclinationX;
		DifZ = *GlobTomb4.pAdr->pInclinationZ;
		// scegliere quali delle due inclinazioni considrare
		// e con uale segno
		Orient = pItem->OrientationH;
		switch (Orient) {
		case 0x0000:
			// asse z (segno normale, credo)
			Scarto = DifZ;
			break;
		case 0x8000:
			// asse z (segno invertito)
			Scarto = -DifZ;
			break;
		case 0x4000:
			// asse x
			Scarto = DifX;
			break;
		case 0xC000:
			// asse  x invertito
			Scarto = -DifX;
			break;
		}
		pItem->OrientationV  += Scarto * 0x800;
		
	}
}

void ProvaInclinazione(void)
{
	int Indice;
	StrItemTr4 *pItem;

	if (&GlobTomb4.pAdr->pLevelNow == 0) return;

	Indice = GlobTomb4.VetRemapObjects[1378];
	if (Indice == -1) return;

	pItem = &GlobTomb4.pAdr->pVetItems[Indice];

	AllineaAFloor(pItem);
	GlobTomb4.VetRemapObjects[1378] = -1;


}

// fare calcolo speciale per kayak:
// se e' kayak vedere se e' in acua o sulla spiaggia

bool IsKayakSpiaggiata(StrItemTr4 *pItem)
{

	short Room;
	void *pFloor;

	Room = pItem->Room;
	pFloor = GetFloor(pItem->CordX,pItem->CordY+256,pItem->CordZ, &Room);

	if (GlobTomb4.pAdr->pVetRooms[Room].FlagsRoom & 1) {
		return false;
	}
	return true;

}

bool EsisteAcqua(DWORD CordX, int CordY, DWORD CordZ, short Room)
{
	int AltezzaAcqua;
	int Altezza;
	void *pFloor;

	pFloor= GetFloor(CordX, CordY, CordZ, &Room);
	if (Room ==-1) return false;

	Altezza= GetHeight(pFloor, CordX, CordY, CordZ);
	if (Altezza == WALL_FLOOR) return false;
	
	if (Altezza < CordY) return false;


	// ok, ora vedere se cordy e altezza acqua corrispondo (circa)
	AltezzaAcqua = GetWaterHeight(CordX, 
								CordY,
								CordZ,
								Room);

	if (AltezzaAcqua == WALL_FLOOR) return false;
	return true;

}
// cerca nuova direzione per deriva
// evitando di andare a sbattere contro muri
void NuovaDirezioneDeriva(StrItemTr4 *pItem, StrRollBoat *pRoll)
{
	int NTentantivi;
	bool TestOk;
	int Valore, Maschera;
	DWORD EndX, EndZ;
	short Orient;
	int IncX, IncZ;
	short Room;


	NTentantivi = 4;
	pRoll->DerivaTotCicli = 
		(GetRandomControl() & 0x1f) + 0x2f;
	do {
		// usare diversi criteri a seconda di dati pRoll
		Valore = 2;
		Maschera = 3;

		if (pRoll->SpeedPitch > 0) {
			Valore = 3;
			Maschera = 5;
		}

		if (pRoll->SpeedSwing & 0x3) {
			Valore --;
			Maschera--;
		}
		if (pRoll->SpeedPitch & 0x10) {
			Valore ++;
			Maschera++;
		}

		if (pRoll->SpeedSwing & 0x08) {
			Valore--;
		}

		if (pRoll->SpeedPitch & 0x08) {
			Maschera--;
		}


		pRoll->DerivaIncX = Valore - (GetRandomControl() & Maschera);
		pRoll->DerivaIncZ = Valore - (GetRandomControl() & Maschera);


		EndX = pItem->CordX + (pRoll->DerivaIncX << 8);
		EndZ = pItem->CordZ + (pRoll->DerivaIncZ << 8);

		// ora calcolare orientamento per direzione
		Orient = mGetAngle(pItem->CordX , pItem->CordZ, EndX, EndZ);
		Orient += 0x4000; // si usa sempre per avere valore ok


		// adesso trovare il punto a distanza 1024
		CalcolaIncremento(Orient, &IncX, &IncZ, 1024);

		EndX = pItem->CordX + IncX;
		EndZ = pItem->CordZ + IncZ;

		// vedere se c'e' acqua in quella stanza
		Room = pItem->Room;

		GetFloor(EndX, pItem->CordY + 256, EndZ, &Room);
		if (Room == -1) {
			TestOk=false;
		}else {
			TestOk=true;
			if (EsisteAcqua(EndX, pItem->CordY + 256, EndZ, Room) == false) {
				TestOk=false;
			}

			if (TestOk) {
				if (EsisteAcqua(EndX+1024, pItem->CordY + 256, EndZ, Room) == false) {
					TestOk=false;
				}
			}

			if (TestOk) {
				if (EsisteAcqua(EndX-1024, pItem->CordY + 256, EndZ, Room) == false) {
					TestOk=false;
				}
			}				

			if (TestOk) {
				if (EsisteAcqua(EndX, pItem->CordY + 256, EndZ+1024, Room) == false) {
					TestOk=false;
				}
			}	

			if (TestOk) {
				if (EsisteAcqua(EndX, pItem->CordY + 256, EndZ-1024, Room) == false) {
					TestOk=false;
				}
			}	


		}
		NTentantivi--;

	}while (NTentantivi > 0 && TestOk==false);

	if (TestOk ==false) {
		pRoll->DerivaIncX=0;
		pRoll->DerivaIncZ =0;
	}


}
// fa rullare tutte le barche previste 
void AggiornaRollBoats(void)
{
	StrRollBoat *pRoll;
	int i;
	short MinOrient;
	short MaxOrient;
	StrItemTr4 *pItem;
	bool TestIgnora;
	bool TestDeriva;
	bool TestSuono;


	pRoll = &GlobTomb4.BaseRollBoats.VetRollBoats[0];

	for (i=0;i<GlobTomb4.BaseRollBoats.TotRollBoats;i++) {
		// non fare nulla se la barca attuale e' indice veicolo
		// corrente
		if (*GlobTomb4.pAdr->pVehicleIndex !=
			pRoll->Indice) {



			TestIgnora=false;

			pItem = &GlobTomb4.pAdr->pVetItems[pRoll->Indice];

			if (pItem->SlotID == 492) {
				// se e' kayak verifcafre che non sia a terra

				TestIgnora=IsKayakSpiaggiata(pItem);
				pRoll->OldCordX =0;
				pRoll->OldCordZ =0;

			}
			if (TestIgnora==false) {
				TestSuono=false;
				TestDeriva = false;
				// vedere se va eliminato o creato il movimento alla deriva
				if (pRoll->Flags & FRB_ALLOW_DRIFT) {
					// consentire deriva
					// se barca non e' ne motoscafo ne' canotto
					// simularla
					if (pItem->SlotID != 465 &&
						pItem->SlotID != 467) {

						// effettuare deriva simulata
						if (pRoll->DerivaTotCicli == 0) {
							NuovaDirezioneDeriva(pItem, pRoll);

						}else {
							AggiornaPosizioneItem(pRoll->Indice, 
								pItem->CordX + pRoll->DerivaIncX,
								pItem->CordY, 
								pItem->CordZ + pRoll->DerivaIncZ,0);


							pRoll->DerivaTotCicli --;
						}

					}
				}else {
					// disattivare deriva
					if (pRoll->OldCordX == 0) {
						// non anocra valore valido
						pRoll->OldCordX = pItem->CordX;
						pRoll->OldCordZ = pItem->CordZ;
					}else{
						// usare vallori precedenti
						pItem->CordX = pRoll->OldCordX;
						pItem->CordZ = pRoll->OldCordZ;
					}

					
				}
				// ok, ora scoprire i range dei due tipi di rolling
				if (pRoll->SpeedPitch) {
					MinOrient = -1024;
					MaxOrient = 1024;

					if (pRoll->Flags & FRB_PITCHING_LOW) {
						MinOrient = MinOrient >> 1;
						MaxOrient = MaxOrient >> 1;
					}

					if (pRoll->Flags & FRB_PITCHING_HIGH) {
						MinOrient = MinOrient << 1;
						MaxOrient = MaxOrient << 1;
					}
					pItem->OrientationV += pRoll->SpeedPitch;
					// vedere se raggiunto limite

					if (pItem->OrientationV <= MinOrient) {
						pRoll->SpeedPitch = -pRoll->SpeedPitch;
						pItem->OrientationV = MinOrient;
						TestSuono=true;
					}

					if (pItem->OrientationV >= MaxOrient) {
						pRoll->SpeedPitch = -pRoll->SpeedPitch;
						pItem->OrientationV = MaxOrient;
						TestSuono=true;
					}
				}
					// stessa cosa ma per swing
				// ok, ora scoprire i range dei due tipi di rolling
				if (pRoll->SpeedSwing ) {
					MinOrient = -2048;
					MaxOrient = 2048;




					if (pRoll->Flags & FRB_SWINGING_LOW) {
						MinOrient = MinOrient >> 1;
						MaxOrient = MaxOrient >> 1;
					}

					if (pRoll->Flags & FRB_SWINGING_HIGH) {
						MinOrient = MinOrient << 1;
						MaxOrient = MaxOrient << 1;
					}
					pItem->OrientationT  += pRoll->SpeedSwing;
					// vedere se raggiunto limite

					if (pItem->OrientationT <= MinOrient) {
						pRoll->SpeedSwing = -pRoll->SpeedSwing;
						pItem->OrientationT = MinOrient;
						if (pRoll->SpeedPitch ==0) TestSuono=true;
					}

					if (pItem->OrientationT >= MaxOrient) {
						pRoll->SpeedSwing = -pRoll->SpeedSwing;
						pItem->OrientationT = MaxOrient;
						if (pRoll->SpeedPitch ==0) TestSuono=true;
					}



				}
				if (TestSuono && pRoll->SoundSfx != -1) {
					SoundEffect(pRoll->SoundSfx, &pItem->CordX, 0);
				}

			}

		}else {
			// la barca e' attualemtne in moto con lara
			// azzerare oldcord
			pRoll->OldCordX =0;
			pRoll->OldCordZ =0;
		}


		pRoll++;
	}


}

// eseguita solo in modalita' taratura detector
// permette di modificare i valori di coordinate per visualzizare
// detector
// accetta tasti [R] [F] per scegliere variabile da modifcare
// e tasti [Y] [U] per cambiare il suo valore
void TaraMieiOggetti(void)
{
	StrCordDetectors *pCord;
	DWORD TempoNow;
	float *pFloat;
	int *pInt;

	pCord = &GlobTomb4.BaseCordDetector;
	TempoNow = GetTickCount();

	if ((TempoNow - pCord->LastCambioVar) > 500) {
		// vedere se cambiare variabile
		if (TastoVKPremuto('R')) {
			// diminuire indici
			pCord->IndiceAttivo--;
			if (pCord->IndiceAttivo < 0) pCord->IndiceAttivo =0;
			pCord->LastCambioVar = TempoNow;
		}

		if (TastoVKPremuto('F')) {
			pCord->IndiceAttivo++;
			if (pCord->IndiceAttivo >= MAX_TARA_ITEMS) pCord->IndiceAttivo=MAX_TARA_ITEMS-1;
			pCord->LastCambioVar = TempoNow;
		}
		
	}

	switch (pCord->IndiceAttivo) {
	case 2:
	case 3:
	case 7:
		// valori float
		pFloat = (float*) &pCord->DetOrgY;

		if (TastoVKPremuto('Y')) pFloat[pCord->IndiceAttivo] -= 1.0f;
		if (TastoVKPremuto('U')) pFloat[pCord->IndiceAttivo] += 1.0f;
		break;
	default:
		pInt = &pCord->DetOrgY;


		if (TastoVKPremuto('Y')) pInt[pCord->IndiceAttivo]--;
		if (TastoVKPremuto('U')) pInt[pCord->IndiceAttivo]++;
		break;

	}



	
}

