void AggiornaColorWhiteMod(void)
{
	BYTE *pByte;
	short Val;
	short Incremento;
	BYTE Single;
	int i;

	pByte = (BYTE *) &GlobTomb4.VetTextColors[1];

	Incremento = GlobTomb4.ColorWhiteStep;

	Val = GlobTomb4.ColorGradientNow;
	Val += Incremento;



	if (Incremento < 0) {
		if (Val <= 0) {
			Val=0;
			Incremento = -Incremento;
		}
	}else {
		if (Val >= 255) {
			Val = 255;
			Incremento = -Incremento;
		}
	}

	Single = Val & 0xff;
	GlobTomb4.ColorGradientNow=Val;
	GlobTomb4.ColorWhiteStep = Incremento;

	for (i=0;i<3;i++) {
		pByte[i] = Single;
	}


}
