// sostituisce ItemNearLara() perche' creava problemi col box di collisione
// sulla coordinata y
// questa procedura verifica se lara ha una distanza < di Distanza da 
// posizione pPos
// nota: il calcolo e' rapido, il che significa che e' certamente giusto
// solo per difetto: se l'esito e' false allora sicuramente lara e' piu'
// lontana della distanza richiesta. mentre se il risultato e' true 
// potrebbe anche accadereche lara sia leggermente piu' lontana della distanza
// richiesta

bool IsItemVicinoLara(StrMovePosition *pPos, int Distanza, bool TestIgnoraY)
{
	int Dif;

	Dif = pPos->RelX - GlobTomb4.pAdr->pLara->CordX;
	if (Dif < -Distanza || Dif > Distanza) return false;

	if (TestIgnoraY ==false) {
		Dif = pPos->RelY - GlobTomb4.pAdr->pLara->CordY;
		if (Dif < -Distanza || Dif > Distanza) return false;
	}
	Dif = pPos->RelZ - GlobTomb4.pAdr->pLara->CordZ;
	if (Dif < -Distanza || Dif > Distanza) return false;

	return true;

}
// verifica se coordinata pPosizione e' piu' vicino di Distanza
// se TestRapido=true e' un calcolo approssimtivo
// mentre se testrapido = alse c'e' un calcolo piu' approfondito
bool IsVicinoALara(StrMovePosition *pPosizione, int Distanza, bool TestRapido)
{
	int DifX, DifZ;
	int Tot;

	if (IsItemVicinoLara(pPosizione, Distanza,false)==false) return false;
	if (TestRapido) return true;

	DifX = pPosizione->RelX - GlobTomb4.pAdr->pLara->CordX;
	DifZ = pPosizione->RelZ - GlobTomb4.pAdr->pLara->CordZ;
	// fare  la potenza di 2 di entrambe ledistnanze
	DifX *= DifX;
	DifZ *= DifZ;

	Tot = DifX + DifZ;
	// ora fare l'estrazione di radice quadra
	if (sqrt(Tot) > Distanza) return false;
	return true;



}
void AddEffectFire(StrItemTr4 *pItem,  int NMesh, 
				   int DispX, int DispY, int DispZ, WORD Flags,
				   int ValIntensita, WORD TestUccide, short TestVertical)
{

	StrMovePosition  TriRec;
	StrItemTr4 FakeItem;
	WORD Orient;
	short OcbValue;
	static int VetSize[] = {150, 200, 300};

	TriRec.RelX = DispX;
	TriRec.RelY = DispY;
	TriRec.RelZ = DispZ;

	// nel caso fosse striscia bisogna pensare anche a modificare orientamento

	Orient = pItem->OrientationV;

	if (Flags & FADD_VORIENT_90) pItem->OrientationV += 0x4000;
	if (Flags & FADD_VORIENT_180) pItem->OrientationV += 0x7fff;
	if (Flags & FADD_VORIENT_270) pItem->OrientationV -= 0x4000;

	TrovaAbsPosition(pItem, &TriRec, NMesh);


	pItem->OrientationV = Orient;

	if (Flags & FADD_FIRE_STRIP) {
		Orient = pItem->OrientationH;
		// invertire sempre
		Orient += 0x8000;

		// striscia di fuoco
		if (Flags & FADD_ROTATE_90) Orient += 0x4000;
		if (Flags & FADD_ROTATE_180) Orient += 0x8000;
		if (Flags & FADD_ROTATE_270) Orient += 0xC000;

		FakeItem.CordX = TriRec.RelX;
		FakeItem.CordY = TriRec.RelY;
		FakeItem.CordZ = TriRec.RelZ;
		FakeItem.Room = pItem->Room;
		FakeItem.OrientationH = Orient;

		if (TestVertical == 1) {
			OcbValue=-1;
		}else {
			OcbValue=-2;
		}
		FakeItem.OcbCode = OcbValue; //OcbValue;  // scoprire cosa cambia

		TriggerSuperJetFlame(&FakeItem, ValIntensita, TestUccide);

		TriggerDynamic(TriRec.RelX , TriRec.RelY , TriRec.RelZ , 0x16, 
				200, 150, 0);

		if ((Flags & FADD_NO_SOUND) == 0) SoundEffect(150, &TriRec, 0);

	}else {

	
		AddFire(TriRec.RelX, TriRec.RelY, TriRec.RelZ, 
				ValIntensita, pItem->Room,0xff);

		if (TestUccide) {
			if ((*GlobTomb4.pAdr->pFlagsLara & 0x08) == 0) {
				// controllare se ha colpito lara
				if (ValIntensita < 0) ValIntensita=0;
				if (ValIntensita > 2) ValIntensita=2;

				if (IsVicinoALara(&TriRec, VetSize[ValIntensita], false)) {
					// bruciare lara
					LaraBurn();

				}
			}
		}					

		if ((Flags & FADD_NO_SOUND) == 0) SoundEffect(0x96, &pItem->CordX, 0);
	}


}
// aggiunge a moveable pItem la luce con i dati richeisti
void AddEffectLight(StrItemTr4 *pItem, int NMesh, int DispX, int DispY, int DispZ,
					int Intensity, int Distance, WORD Flags, 
					int Colore, int TipoLuce)
{
	WORD Orient;
	StrMovePosition  TriRec;
	DWORD SalvaRosso;
	DWORD SalvaVerde;
	DWORD SalvaBlu;
	DWORD SalvaIntensita;
	WORD SalvaFlags;
	StrMovePosition FinePoint;
	DWORD ColoreRGB;

	static DWORD VetColori[] = {0xffffff,0xff0000 ,0x00ff00,0x0000ff,
		0xffff00, 0x00ffff , 0xff00ff};
	BYTE *pColors;

	TriRec.RelX = DispX;
	TriRec.RelY = DispY;
	TriRec.RelZ = DispZ;

	pColors = (BYTE *) &VetColori[Colore];

	Orient = pItem->OrientationV;
	if (Flags & FADD_VORIENT_90) pItem->OrientationV += 0x4000;
	if (Flags & FADD_VORIENT_180) pItem->OrientationV += 0x7fff;
	if (Flags & FADD_VORIENT_270) pItem->OrientationV -= 0x4000;
	TrovaAbsPosition(pItem, &TriRec, NMesh);
	pItem->OrientationV = Orient;

	switch (TipoLuce) {

	case ADD_LIGHT_FLAT:
		TriggerDynamic(TriRec.RelX , TriRec.RelY , TriRec.RelZ , Intensity, 
				pColors[2], pColors[1], pColors[0]);
		break;
	case ADD_LIGHT_GLOVE:
		ColoreRGB = pColors[0] + (pColors[1] << 8) + (pColors[2] << 16) + 
				(Intensity << 24);
		TriggerLightningGlow(TriRec.RelX, TriRec.RelY, TriRec.RelZ, ColoreRGB);
		break;

	case ADD_LIGHT_BLINK:
		// prima salvare i valori attuali
		SalvaVerde = FlareVerde;
		SalvaRosso = FlareRosso;
		SalvaBlu = FlareBlu;
		SalvaIntensita = FlareIntensita;
		SalvaFlags = GlobTomb4.pBaseCustomize->BaseFlare.Flags;

		// ora impostare i valori
		FlareRosso = (pColors[2] & 0xc0);
		FlareVerde = (pColors[1] & 0xc0);
		FlareBlu = (pColors[0] & 0xc0);
		FlareIntensita = Intensity;
		GlobTomb4.pBaseCustomize->BaseFlare.Flags=0;

		DoFlareLight(&TriRec, 100);

		// ora rirpsitinare i dati gobaoi di flare
		FlareVerde= SalvaVerde;
		FlareRosso = SalvaRosso;
		FlareBlu = SalvaBlu;
		FlareIntensita = SalvaIntensita;
		GlobTomb4.pBaseCustomize->BaseFlare.Flags = SalvaFlags;
		break;
	case ADD_LIGHT_SPOT:
		// calcolare punto inale
		FinePoint.RelX = DispX;
		FinePoint.RelY = DispY;
		FinePoint.RelZ = DispZ + (Distance * 1024);
		GetJointAbsPosition(pItem, &FinePoint, NMesh);
		
		Orient = pItem->OrientationH;

		// vedere se va alterato
		if (Flags & FADD_ROTATE_90) Orient += 0x4000;
		if (Flags & FADD_ROTATE_180) Orient += 0x8000;
		if (Flags & FADD_ROTATE_270) Orient += 0xC000;

		LaraTorch(&TriRec, &FinePoint, Orient, Intensity);
		break;

	}



}

