DWORD LastFmvTime;

// log chiamato sempre per fmv ma basta mettere qui un return per eliminarne gli effetti
void PrintFmvLog(char *pMex)
{
	return;

	FILE *pFile;
	DWORD TimeNow;
	DWORD TempoTrascorso;
	
	TimeNow=GetTickCount();
	TempoTrascorso=TimeNow-LastFmvTime;
	LastFmvTime= TimeNow;


	pFile=fopen("fmv_log.txt","a+b");
	if (pFile==NULL) return;
	fprintf(pFile, "[%d ms]: %s\r\n", TempoTrascorso, pMex);

	fclose(pFile);

}

void InitFmvLog(char *pMex, bool TestCancellaLog)
{
	return;
	LastFmvTime=GetTickCount();
	if (TestCancellaLog) {
		remove("fmv_log.txt");
	}
	PrintFmvLog(pMex);
}

// salva in fondo a file pNomeFile il vettore di dati word VetExtra
// contenente TotItems elementi
// nota: il vettore VetExtra deve contenere solo i dati effettivi
//		escludendo la word di controllo inizale "NG" e l'header
//		finale NGLE/Size
// Se c'e' un errore resituisce false
// note: il file pNomeFile verra' aperto da questo funzione e per questa
//		ragione, e' importante che NON risulti gia' aperto altrinenti
//      ci sara' un errore
bool WriteNGHeader(char *pNomeFile, WORD *VetExtra, DWORD NWords)
{
	FILE *pFile;
	WORD NumeroW;
	StrEndNgHeader EndHeader;
	int TotWords;

	if (EsisteFile(pNomeFile)==false) return false;
	
	pFile = fopen(pNomeFile,"a+b");
	if (pFile == NULL) return false;

	// salvare prima word di verifica
	TotWords = NWords;

	NumeroW = NG_SHORT_CHECK;    // "NG"
	fwrite(&NumeroW, 1,2,pFile);
	TotWords++;

	// ora salvare l'intero vettore
	fwrite(VetExtra,NWords,2,pFile);
	// quindi mettere le due word consecutive azzerate finali
	NumeroW=NGTAG_END_SEQUENCE;

	fwrite(&NumeroW,1,2,pFile);
	fwrite(&NumeroW,1,2,pFile);
	TotWords += 2;

	// e infine salvare l'header finale
	EndHeader.EndCheck = NG_LONG_CHECK; // valore controllo "NGLE"
	EndHeader.SizeNgHeader = TotWords*2 + sizeof(StrEndNgHeader);

	fwrite(&EndHeader,sizeof(StrEndNgHeader),1,pFile);

	fclose(pFile);
	return true;
}
// sulla base del nome del file restituisce la costante del tipo 
// di file:
// #define CTE_UNKNOWN 0
// #define CTE_TOM  1
// #define CTE_PRJ  2
// #define CTE_SAVEGAME 3
// #define CTE_TR4 4
// #define CTE_WAD 5
// #define CTE_DAT 6
int TrovaTipoFile(char *pNomeFile) 
{

	char *pMex;
	static char * VetEstensioni[] = {NULL, "tom", "prj", NULL, 
								"tr4", "wad", "dat"};
	const int TotEstensioni = 7;
	int i;

	pMex = SoloNomeSenzaExt(pNomeFile);
	if (strcmpi(pMex,"savegame")==0 || 
		strcmpi(pMex,"backgame")==0 ) return CTE_SAVEGAME;

	// per gli altri file invece usare estensione
	pMex = SoloEstensione(pNomeFile);
	for (i=0;i<TotEstensioni;i++) {
		if (VetEstensioni[i] != NULL && 
			strcmpi(pMex, VetEstensioni[i]) ==0) return i;
	}
	return CTE_UNKNOWN;
}
// usata per riempiere word di header ng
// inserisce ValDword in vettore pVetWords sotto forma di due word nel formato
// basso / alto
// inserisce il valore e aggiorna pTotItems
void ScriviDword2VetWords(DWORD ValDword, WORD *pVetWords, int *pTotItems)
{
	DWORD *pDword;

	pDword = (DWORD *) &pVetWords[*pTotItems];
	*pDword = ValDword;
	*pTotItems +=2;

}
// estrare da VetWords la DWORD memorizzata a partire da Indice
// aggiorna anche il valroe di Indice
DWORD LeggiDwordFromVetWords(WORD *pVetWords, int *Indice)
{
	DWORD *pDword;

	pDword = (DWORD *) &pVetWords[*Indice];
	*Indice+=2;
	return *pDword;

}
