// ripristina modifiche per danno di creeture a lara e azzera
// totEnemy
// VetDamage
void RipristinaEnemy(void)
{
	int i;
	char *pByte;
	short *pShort;
	int *pInt;

	GlobTomb4.BaseEnemys.TotEnemy=0;

	i=0;
	while (VetDamage[i].pOffset != 0) {
		// riscrivere tutti i valori originali
		switch (VetDamage[i].Tipo) {
		case 'B':
			pByte = (char*) VetDamage[i].pOffset;
			*pByte = (char) VetDamage[i].ValoreOriginale;
			break;
		case 'W':
			pShort = (short*) VetDamage[i].pOffset;
			*pShort = (short) VetDamage[i].ValoreOriginale;
			break;
		case 'D':
			pInt = (int*) VetDamage[i].pOffset;
			*pInt = (int) VetDamage[i].ValoreOriginale;
			break;
		}
		i++;
	}	

}


// modifica i damage sulla base di elenco Enemy
void ImpostaEnemyDamage(void)
{
	StrRecordEnemyScript *pEnemy;
	int i,j;
	int TotEnemy;
	int  VetDiversi[10];
	int TotDiversi;
	WORD SlotNow;
	int Indice;
	int NuovoValore;
	char *pByte;
	short *pShort;
	int *pInt;
	int ValoreDefault;
	bool TestIgnora;

	TotEnemy=GlobTomb4.BaseEnemys.TotEnemy;

	for (i=0;i<TotEnemy;i++) {
		pEnemy = &GlobTomb4.BaseEnemys.VetEnemy[i];
		TotDiversi=0;
		SlotNow=pEnemy->SlotId;
		// cercare tutti i valori corrispondenti a SlotNow

		
		Indice =0;

		while (VetDamage[Indice].pOffset !=0) {
			if (VetDamage[Indice].Slot == SlotNow) {
				// ok, trovato
				// ora capire qual'e' il valore da usare
				for (j=0;j<TotDiversi;j++) {
					if (VetDamage[Indice].ValoreOriginale == VetDiversi[j]) break;
				}
				if (j == TotDiversi) {
					// non c'era, salvarlo adesso
					VetDiversi[j] = VetDamage[Indice].ValoreOriginale;
					TotDiversi++;
				}
				// adesso va usato il valore in j in extradamage
				// controllare che sia presente
				TestIgnora=false;
				if (j >= pEnemy->TotDamage) TestIgnora=true;
				if (pEnemy->VetDamage[j]== -1) TestIgnora=true;

				if (TestIgnora==false) {

					NuovoValore = pEnemy->VetDamage[j];
					// se il valore e' negativo, fare inversione
					ValoreDefault = (int) VetDamage[Indice].ValoreOriginale;
					if (ValoreDefault < 0) {
						// era negativo, invertire il segno anche di valore
						// da impostare
						NuovoValore = -NuovoValore;

					}
					switch (VetDamage[Indice].Tipo) {
					case 'B':
						pByte = (char*) VetDamage[Indice].pOffset;
						*pByte = (char) NuovoValore;
						break;
					case 'W':
						pShort =(short*) VetDamage[Indice].pOffset;
						*pShort = (short) NuovoValore;
						break;
					case 'D':
						pInt = (int*) VetDamage[Indice].pOffset;
						*pInt = (int) NuovoValore;
						break;
					}
				}
			}
			Indice++;

		}

	}
		



}
// salva i dati cust_weap appena letti da script
void InitWeaponCust(short SlotArma, short VetArg[], bool TestTitle)
{
	StrCustWeapon *pWeap;
	StrCustWeapon *pDef;

	switch (SlotArma) {
	case 349: // PISTOLS_ITEM
		pWeap = &GlobTomb4.pBaseCustomize->WeaponPistols;
		pDef = &GlobTomb4.pBaseCustomizeDefault->WeaponPistols;
		break;
	case 351:  // UZI_ITEM
		pWeap = &GlobTomb4.pBaseCustomize->WeaponUzi;
		pDef = &GlobTomb4.pBaseCustomizeDefault->WeaponUzi;
		break;	
	case 353: // SHOTGUN_ITEM
		pWeap = &GlobTomb4.pBaseCustomize->WeaponFucile;
		pDef = &GlobTomb4.pBaseCustomizeDefault->WeaponFucile;
		break;
	case 356: // CROSSBOW_ITEM
		pWeap = &GlobTomb4.pBaseCustomize->WeaponBalestra;
		pDef = &GlobTomb4.pBaseCustomizeDefault->WeaponBalestra;
		break;
	case 361: // GRENADE_GUN_ITEM
		pWeap = &GlobTomb4.pBaseCustomize->WeaponLanciaGranate;
		pDef = &GlobTomb4.pBaseCustomizeDefault->WeaponLanciaGranate;
		break;
	case 366:  // SIXSHOOTER_ITEM (revolver)
		pWeap = &GlobTomb4.pBaseCustomize->WeaponRevolver;
		pDef = &GlobTomb4.pBaseCustomizeDefault->WeaponRevolver;
		break;
	}

	// argomenti:
	// 0: Weapon flags (WEAP_..) 
	if (VetArg[0] !=-1 ) pWeap->Flags = VetArg[0];

	// 1: SoundForShot
	if (VetArg[1] != -1) pWeap->SoundShot  = VetArg[1];

	// 2: FramesForRecharge
	if (VetArg[2] != -1) pWeap->FramesRicarica = (BYTE) VetArg[2];

	// 3: DurateFlash
	if (VetArg[3] != -1) pWeap->SizeShell = (BYTE) VetArg[3];

	// 4: Extra
	if (VetArg[4] != -1) pWeap->Extra = VetArg[4];

	// 5: MaxDistanceForAiming
	if (VetArg[5] !=-1) pWeap->DistanceAiming = VetArg[5] * 1024;

	// 6: FrameToTakeWeapon
	if (VetArg[6] !=-1) pWeap->FrameToTakeWeapon = (BYTE) VetArg[6];

	// 7: FrameToLetWeapon
	if (VetArg[7] != -1) pWeap->FrameToLetWeapon = (BYTE) VetArg[7];

	// 8: Random dispersione
	if (VetArg[8] != -1)  pWeap->Dispersion = VetArg[8];

	// 9: VPositionOfWeapon
	if (VetArg[9] != -1) pWeap->VPositionOfWeapon = VetArg[9];
	
	// 10: Unknown, 
	if (VetArg[10] != -1) pWeap->Unknow = VetArg[10];

	// 11: FrameCounter
	if (VetArg[11] != -1) pWeap->FrameCounter = (BYTE) VetArg[11];

	// 12: FrameMinRange
	if (VetArg[12] != -1) pWeap->FrameMinRange = (BYTE) VetArg[12];

	// 13: FrameMaxRange
	if (VetArg[13] != -1) pWeap->FrameMaxRange = (BYTE) VetArg[13];

	// 14: OrigX
	if (VetArg[14] != -1) pWeap->OrigX = VetArg[14];
	
	// 15: OrigY
	if (VetArg[15] != -1) pWeap->OrigY = VetArg[15];

	// 16: OrigZ
	if (VetArg[16] != -1) pWeap->OrigZ = VetArg[16];

	// 17: OrigOrient
	if (VetArg[17] != -1) pWeap->Orient = VetArg[17];

	if (TestTitle) {
		memcpy(pDef,pWeap, sizeof(StrCustWeapon));
	}
}
