							pTestPosition->DatiPosition.Distance.MaxX =
								ParseField.pData[i++];
							// y range
							pTestPosition->DatiPosition.Distance.MinY =
								ParseField.pData[i++];
							pTestPosition->DatiPosition.Distance.MaxY =
								ParseField.pData[i++];
							// z range
							pTestPosition->DatiPosition.Distance.MinZ =
								ParseField.pData[i++];
							pTestPosition->DatiPosition.Distance.MaxZ =
								ParseField.pData[i++];

							// diff orient horizzontal
							pTestPosition->DatiPosition.Orienting.OrientHMin =
								ParseField.pData[i++];
							pTestPosition->DatiPosition.Orienting.OrientHMax =
								ParseField.pData[i++];
							// diff orient vertiale
							pTestPosition->DatiPosition.Orienting.OrientVMin =
								ParseField.pData[i++];
							pTestPosition->DatiPosition.Orienting.OrientVMax =
								ParseField.pData[i++];
							// diff orient rotate
							pTestPosition->DatiPosition.Orienting.OrientRMin =
								ParseField.pData[i++];
							pTestPosition->DatiPosition.Orienting.OrientRMax =
								ParseField.pData[i];

							GlobTomb4.BaseTestPosition.TotTestPositions++;
