// chiama GestioneCicloPrincipale() di tomb4
// proteggendolo o meno da crash a seconda di preferenze
int GosubCicloPrincipale(int Arg1, int Arg2)
{
	int ValReturn;

	if (GlobTomb4.MyPrefTomb.Flags & FPT_NO_RESUME_CRASH) {
		return tombCicloPrincipale(Arg1,Arg2);

	}
	// eseguirlo con controllo crash
	TestBloccoTRY++;
	try {
		ValReturn=tombCicloPrincipale(Arg1,Arg2);
	} 
	catch (...) {
		InviaLog("Resumed crash in MainCycle()");
		RimuoviMonoScreen();
		ValReturn=0;
	}
	TestBloccoTRY--;
	return ValReturn;


}

