// verifica se su uno dei due canali (0 e 1) non e' presente qalcuna traccia audio
// e se c'era una precedente traccia su quel canale (interrotta) da far ripartire
void GestioneRestartAudioTracks(void)
{
	StrCanaleBass *pCanale;
	StrPauseOldChannel *pPausa;
	StrBassHandles *pBass;
	int i;
	bool TestMuto;

	if (GlobTomb4.pBaseCustomize->TipoCDM == CDM_NO_SAVE) return;

	pBass= &GlobTomb4.BaseBassHandles;
	for (i=0;i < 2;i++) {
		pCanale = &pBass->VetCanali[i];
		pPausa = &GlobTomb4.pMisc->VetPauseTracks[i];

		if (pPausa->CD_Track != -1) {
			// vedere se questo canale e' muto
			TestMuto=false;
			if (pCanale->Canale == 0) {
				TestMuto=true;
			}else {
				if (pBass->Proc.BASS_ChannelIsActive(pCanale->Canale) ==0) {
					TestMuto=true;
				}
			}

			if (TestMuto) {
				pPausa->SilentCounter++;
				if (pPausa->SilentCounter >= 15) {
					// far riparire vecchia traccia audio sul precedente canale
					switch (GlobTomb4.pBaseCustomize->TipoCDM) { 
					case CDM_RESTORE_FROM_BEGIN:
						GlobTomb4.BaseBassHandles.CanaleNow = i | 0x40;
						GestioneCdPlay(pPausa->CD_Track, 0);
						break;
					case CDM_RESTORE_FROM_MIDDLE:
						GlobTomb4.BaseBassHandles.StartOffset = pPausa->Position;
						GlobTomb4.BaseBassHandles.CanaleNow = i | 0x40;
						GestioneCdPlay(pPausa->CD_Track, 0);
						break;

					}
					
					// azzerare questo record pausa
					pPausa->CD_Track=-1;
					pPausa->SilentCounter=0;
				}
			}else {
				// c'e' un suono: azzerare contatore
				pPausa->SilentCounter=0;
				// se il suono e' lo stesso old allora azzerare tutto il record pausa
				if (pCanale->NumeroCd == pPausa->CD_Track) {
					pPausa->CD_Track=-1;
				}

			}
		}
	}


}


