// usato per alcuni log: restituisce una stringa con tutti i byte richiesti in hex
char *GetByteStrip(BYTE *pBytes, int TotBytes)
{
	int i;
	char MiniBuf[4];
	static char Buffer[256];

	Buffer[0]=0;
	for (i=0;i<TotBytes;i++) {
		sprintf(MiniBuf, "%02X", pBytes[i]);
		strcat(Buffer, MiniBuf);

	}
	return Buffer;

}
