// verifica se esiste un triggergroup da esguire al frame attuale, nell'orgaznier collegato al demo attuale
void GestioneDemoOrganizer(StrDemo *pDemo, int IndexFrame) 
{
	int i;

	if (pDemo->pOrganizer == NULL) return;

	if (GlobTomb4.TestEditingDemo==true && GlobTomb4.TestDisableDemoOrganizer == true) return;

	for (i=0;i<pDemo->pOrganizer->TotCoppie;i++) {
		if (pDemo->pOrganizer->VetCoppie[i].Secondi == IndexFrame) {
			GlobTomb4.pMexLastTGCaller = "Demo Organizer";
			FormattaLogCutscene("ORGANIZER", IndexFrame, "TriggerGroup=%d", pDemo->pOrganizer->VetCoppie[i].IdGroup , 0);
			EseguiTriggerGroup(pDemo->pOrganizer->VetCoppie[i].IdGroup);
			
		}
		if (pDemo->pOrganizer->VetCoppie[i].Secondi > IndexFrame) break;
	}


}
// chiamata all'inizio e alla fine di demo playing. viene passato il demotitle (se c''e un title in progress
// da title) o altrimento demolevel.
// se testinprogress=false non fa niente.
// usa flag FGD_...
// altrimenti gestisce inizio e fine di demo script command
// gestisce sia inizio che fine.
// se e' fine e demotitle restituisce un valore per dire che cosa fare dopo:
// nota: se ritonra 0 bisognera'tornare  atitle 
//  se ritorna "1" vuol dire che bisogna chiamare subito di nuovo GestioneDemo() perche'
//			e' stato caricato un nuovo demo di stesso livello
// se ritorna "2" vuol dire che si deve caricare un nuovo livello con un nuovo demo


int GestioneDemoInProgress(WORD FlagGestioneDemo, StrDemo *pDemo)
{

	int NuovoLivello;
	int i;
	int DemoId;
	static int *pVolumeSfxNow = (int*) 0x537320; // VolumeSFX_Now
	static int *pSettingsSfxVolume = (int*) 0x4B1714; // Setting_SFXVolume
	static int *pSettingsMusicVolume = (int*) 0x4B1710; // Setting_MusicVolume
	static short *pTestAttivoFade = (short *) 0x4BF254;
	static char BufDemoLegend[256];
	StrScriptOrganizer *pOrganizer;

	// eseguire cutscene camera
	if ((GlobTomb4.pBaseDemo->Status & RECF_RECORDING)==0) AggiornaCutsceneCamera(&GlobTomb4.pBaseCutscene->BaseCamera);

	if (FlagGestioneDemo & FDG_START) {
	// ******************************** START OF DEMO *****************************
		// salvare sempre volume di sfx e music originale (male non fa)
		if (GlobTomb4.TestEditingDemo==true && GlobTomb4.pBaseDemo->Status & RECF_PLAYING) {
			// salvare l'indizio di un nuovo play
			FormattaLogCutscene("DEMO", 0, "-------- BEGIN PLAYING DEMO%d.PAK ----------\r\n", GlobTomb4.DemoNumberLoaded,0);


		}
		pDemo->SalvaSfxVolume = *pSettingsSfxVolume;
		pDemo->SalvaMusicVolume = *pSettingsMusicVolume;

		// vedere se c'e' un organizer collegato a queso demo
		pDemo->pOrganizer=NULL;

		for (i=0;i<GlobTomb4.pBaseOrganizer->TotOrganizer;i++) {
			pOrganizer= &GlobTomb4.pBaseOrganizer->VetOrganizer[i];

			if (pOrganizer->Flags & FO_DEMO_ORGANIZER) {
				if (pOrganizer->Parameter == GlobTomb4.DemoNumberLoaded) {
					// si
					pDemo->pOrganizer = pOrganizer;
					break;
				}
			}
		}


		// se siamo in modo esegui demo vedere inizializzazione

		// disattivare suoni sfx?
		if (pDemo->Flags & DEMF_MUTE_SFX) {
			StopAllSounds();
			*pSettingsSfxVolume=0;
		}
	
		// disattivare suono musica?
		if (pDemo->Flags & DEMF_MUTE_TRACK) {
			StopBassSuoni(-1);
			*pSettingsMusicVolume=0;
			ACMSetVolume();
		}

		// attivare fade-in?
		if (pDemo->Flags & DEMF_CROSS_FADE) {
			
			*pTestAttivoFade=0;
			SetScreenFadeIn(16);
		}

		// usare cinema effect?
		if (pDemo->Flags & DEMF_CINEMA_SCREEN) {
			// se pero' siamo in modalitga' editing NON attivarlo
			if (GlobTomb4.TestEditingDemo ==false)	EsecuzioneFlipeffect(0,369, 2,SCANF_DIRECT_CALL);

		}



		
	}

	if (FlagGestioneDemo & FDG_IN_PROGRESS) {

		//  ************************ PLAYING IN PROGRESS *****************************

		if (pDemo->StringDemoLegendIndex != -1 && pDemo->TestDemoInProgress == true ) {
			if ((FindSkipPhase() & SKIP_FLY_CAMERA) == 0 || GlobTomb4.pBaseCustomize->TestPrintOnFlyby == true) {
				strcpy(BufDemoLegend, GetString(pDemo->StringDemoLegendIndex));
				StampaStringaDef(BufDemoLegend, 1);
			}
			
		}
		// se rischiesto cross fade iniziare un secondo prima della fine del demo
		if ((pDemo->Flags & DEMF_CROSS_FADE) != 0) {
	
			if ((GlobTomb4.pBaseDemo->TotFrames - GlobTomb4.pBaseDemo->IndexFrame) == 30) {
				SetScreenFadeOut(16,0);
			}
		}

		GestioneDemoOrganizer(pDemo, GlobTomb4.pBaseDemo->IndexFrame);

	}

	if (FlagGestioneDemo & FDG_END) {
		// *************************** COMPLETED DEMO ****************************

		pDemo->TestDemoInProgress =false;
		pDemo->TestLoadAndPlay = false;
		pDemo->TestTornaATitle=false;

		if (pDemo->Flags & DEMF_MUTE_SFX) {

			StopAllSounds();
			*pVolumeSfxNow = pDemo->SalvaSfxVolume;
			*pSettingsSfxVolume = pDemo->SalvaSfxVolume;

		}

		if (pDemo->Flags & DEMF_MUTE_TRACK) {
			StopBassSuoni(-1);
			*pSettingsMusicVolume = pDemo->SalvaMusicVolume;
			
			ACMSetVolume();
			
		}

		// toglire cinemaeffect?
		if (pDemo->Flags & DEMF_CINEMA_SCREEN) {
			// se eravamo in modalita' editing non c'e' bisogno
			if (GlobTomb4.TestEditingDemo==false) EsecuzioneFlipeffect(0,369,0,SCANF_DIRECT_CALL);
		}

		GestioneDemoOrganizer(pDemo, GlobTomb4.pBaseDemo->IndexFrame);

		if ((FlagGestioneDemo & (FDG_END_FOR_ESCAPE | FDG_END_FOR_TRIGGER)) ==0) {

			// terminato demo precedente (completato in modo normale: no break)

			// vedere se c'e' un altro demo da caricare
			if (pDemo->Flags & DEMF_PLAY_LEVEL_SEQUENCE) {
				// vedere se il prossimo id ha lo stesso livello attuale
				for (i=0;i<pDemo->TotDemoIDs;i++) {
					if (pDemo->VetDemoIDs[i] == pDemo->LastIdPlayed) break;
				}

				i++;

				if (i < pDemo->TotDemoIDs) {
					DemoId= pDemo->VetDemoIDs[i];
					if (CaricaDemo(DemoId)==true) {
						
						if (GlobTomb4.pBaseDemo->DatiLara.pLevelNow == *GlobTomb4.pAdr->pLevelNow) {
							// tutto ok: e' stesso livello per cui basta solo attivare di nuovo il playing
							GlobTomb4.TestEditingDemo=false;
							pDemo->TestDemoInProgress =true;
							pDemo->LastIdPlayed = DemoId;
							pDemo->VetDemoPlayed[i]++;
							GlobTomb4.pBaseDemo->IndexFrame=0;
							GlobTomb4.pBaseDemo->Status = RECF_PLAYING;
							GlobTomb4.DemoNumberLoaded= DemoId;
							return 1;
						}
					}
				}
			}

			if (pDemo->Flags & DEMF_PLAY_ALL_SEQUENCE) {
				for (i=0;i<pDemo->TotDemoIDs;i++) {
					if (pDemo->VetDemoIDs[i] == pDemo->LastIdPlayed) break;
				}

				i++;

				if (i < pDemo->TotDemoIDs) {
					DemoId= pDemo->VetDemoIDs[i];
					
					if (CaricaDemo(DemoId)==true) {
						GlobTomb4.DemoNumberLoaded= DemoId;
						pDemo->LastIdPlayed = DemoId;
						GlobTomb4.TestEditingDemo=false;
						GlobTomb4.pBaseDemo->Status = RECF_PLAYING;
						pDemo->VetDemoPlayed[i]++;

						// ok, controllare se il livello e' uguale al precedente
						if (GlobTomb4.pBaseDemo->DatiLara.pLevelNow == *GlobTomb4.pAdr->pLevelNow) {
							// tutto ok: e' stesso livello per cui basta solo attivare di nuovo il playing
							pDemo->TestDemoInProgress =true;

							return 1;
						}
						
						// livello e' diverso: iniziare procedura per caricare un nuovo livello
						
						NuovoLivello = GlobTomb4.pBaseDemo->DatiLara.pLevelNow;
						*GlobTomb4.pAdr->pInputExtGameCommands=0;
						pDemo->TestLoadAndPlay =true;
						return 2;
					}
				}
			}
						
		}
		if (FlagGestioneDemo & FDG_FROM_TITLE) pDemo->TestTornaATitle =true;						
			
		*GlobTomb4.pAdr->pInputExtGameCommands=0;
		// attivare fade-in?
		if (pDemo->Flags & DEMF_CROSS_FADE) {
			
			*pTestAttivoFade=0;
			SetScreenFadeIn(16);
		}		

	}


	return 0;

}
// usata per registrare in demo i comandi di gioco
// se sono stati premuti tasti numerici 0-9 restituisce una dword specialie con questi tasti premuti
// se non ci sono tasti numerici premuti restituisce normale solo *GlobTomb4.pAdr->pInputExtGameCommands
// nota: se ci sono tasti numerici viene imposta a 1 bit piu' significativo 0x80000000
// e nella parte bassa ci saranno i bit, ogni bit 1 vuol dire che quel tasto numerico e' stato premuto
// l'ordine dei tasti parte da "1" e finisce con "0"
DWORD ReadCurrentGameCommands(void)
{
	DWORD Flags;
	int i;

	Flags=0;

	for (i=2;i<12;i++) {
		if (GlobTomb4.pAdr->pVetInputKeyboard[i]) {
			Flags |= 1;
		}
		Flags = Flags << 1;
	}

	if (Flags) {
		// ci sono tasti numerici, restituire solo quelli
		Flags |= 0x80000000;
		return Flags;
	}

	return *GlobTomb4.pAdr->pInputExtGameCommands;


}
// riceve in input i comandi relativi a comandi di gioco e restituisce una lista testuale di questi comandi.

char *FormattaGameCommands(DWORD Flags) 
{

	static char MioBuffer[256];
	int i;
	static char *VetMexComandi[] = {"Forward", "Backward", "Left", "Right", 
					"Jump", "DrawWeapon", "Action", "Walk", 
					"Inventory", "Look", "$400", "$800",
					"Roll", "Pause", "$4000", "$8000", 
					"$10000", "$20000", "$40000", "UseFlare", 
					"$100000", "$200000", "SaveGame", "LoadGame",
					"$1000000", "$2000000", "$4000000", "$8000000", 
					"$10000000", "Duck", "Dash","$80000000"};

	MioBuffer[0]=0;

	for (i=0;i<32;i++) {
		if (Flags & 1) {
			strcat(MioBuffer, VetMexComandi[i]);
			strcat(MioBuffer, " ");
		}
		Flags = Flags >> 1;
	}

	return MioBuffer;
}
// decomprime (se necessario) i dati CommandData che erano stati registrati in demo
// se ci sono tasti numerici premuti li attiva e poi restituisce
// solo i tasti flag
DWORD DecodeGameCommand(DWORD CommandData)
{
	int i;
	char *pMex;
	char MioBuffer[256];
	char MiniBuf[20];
	int n;

	if ((CommandData & 0x80000000)==0) {
		// se e' attivo cutscene_log mettere messaggio
		if (CommandData != 0 && (GlobTomb4.ScriptOptions.MainFlags & ngfm_Diagnostica) &&
			(GlobTomb4.pDiagnostica->DgxExtra & EDGX_CUTSCENE_LOG)) {
			pMex= FormattaGameCommands(CommandData);
			FormattaLogCutscene("DEMO", GetCutsceneFrame(), pMex,0,0);
		}

		return CommandData;
	}

	// sono tasti numerici: riattivarli 
	MioBuffer[0]=0;

	for (i=11;i >=2;i--) {
		CommandData = CommandData >> 1;
		if (CommandData & 1) {
			GlobTomb4.pAdr->pVetInputKeyboard[i] =1;
			if ((GlobTomb4.ScriptOptions.MainFlags & ngfm_Diagnostica) &&
				(GlobTomb4.pDiagnostica->DgxExtra & EDGX_CUTSCENE_LOG)) {
				n=i-1;
				if (n==10) n=0;
				sprintf(MiniBuf, "Key %d ", n);
				strcat(MioBuffer,MiniBuf);
			}
		}


	}

	if ((GlobTomb4.ScriptOptions.MainFlags & ngfm_Diagnostica) &&
		(GlobTomb4.pDiagnostica->DgxExtra & EDGX_CUTSCENE_LOG)) {
		FormattaLogCutscene("DEMO", GetCutsceneFrame(), MioBuffer,0,0);
	}

	return 0;
}

// nota: se TestFakeUpdateInput = true,  vuol dire che e' stata chiamata da LeggiDirectInput o altra gestione
// mia interna

void GestioneDemo(bool TestFakeUpdateInput)
{
	StrRecording *pRec;
	StrItemTr4 *pLara;

	StrGlobAddress *pAdr;
	StrDemo *pDemo;
	WORD *pVetOrient = (WORD *) 0x80DF62;
	DWORD BaseMeshLara;


	int OffsetMesh;
	int i;
	int *pOggettoSelezionato = (int*) 0x4AC05C;
	int *pZonaSave_9d_CordYDaPeloAcqua = (int*) 0x80DF06;
	bool TestOkEscape;

	WORD FlagGDemo;


	pRec = GlobTomb4.pBaseDemo;

	

	switch (pRec->Status) {
	case RECF_RECORDING:
		if (pRec->TotFrames==0) {
			SalvaDatiInizioDemo(pRec);
			
		}
		GestioneComandiSpeech();
		GestioneDemoOrganizer(GlobTomb4.pDemoLevel, pRec->IndexFrame);
		// controllo per superamento limiti
		if (pRec->TotFrames >= MAX_DEMO_FRAMES) {
			pRec->Status = RECF_STOP;
			TerminaAllSpeech();
			SalvaDemo(GlobTomb4.DemoNumberLoaded );
			InviaLog("WARNING: reached max frame quantity for demo recording. The recording has been stopped");
			break;
		}


		pRec->VetFrames[pRec->TotFrames++] = ReadCurrentGameCommands();
		pRec->IndexFrame = pRec->TotFrames;
		break;
	case RECF_PLAYING:
		FlagGDemo= FDG_NONE;

		if (GlobTomb4.pDemoTitle->TestDemoInProgress) {
			pDemo = GlobTomb4.pDemoTitle;
			FlagGDemo= FDG_FROM_TITLE;
		}else {
			pDemo= GlobTomb4.pDemoLevel;
		}
		
		if (pRec->IndexFrame ==0 ) {

			GestioneDemoInProgress(FlagGDemo | FDG_START, pDemo);

			// ora ripristinare tutti valori globali
			pAdr = GlobTomb4.pAdr;

			if (pRec->DatiLara.pLevelNow != *pAdr->pLevelNow) {
				sprintf(BufferLog, "ERROR: current demo to play has been recorded to work on level %d, while now we are in level %d",
					pRec->DatiLara.pLevelNow, *pAdr->pLevelNow);
				InviaLog(BufferLog);
				pRec->Status = RECF_STOP;
				TerminaAllSpeech();
				break;
			}
			*pAdr->pEarthQuake = pRec->DatiLara.EarthQuake;
			*pAdr->pTestFlybyInProgress = pRec->DatiLara.TestFlybyInProgress;
			*pAdr->pTimerScreen = pRec->DatiLara.TimerScreen;
			*pAdr->pFlareLifeTime = pRec->DatiLara.FlareLifeTime;
			*pAdr->pObjectActive = pRec->DatiLara.ObjectActiveIndex;
			*pAdr->pFlagsLaraHands  =pRec->DatiLara.FlagsLaraHands;
			*pAdr->pObjInLaraHandsNow  =pRec->DatiLara.ObjInLaraHandsNow;
			*pAdr->pObjInLaraHandsNext  =pRec->DatiLara.ObjInLaraHandsNext;
			*pAdr->pWeaponSelected  =pRec->DatiLara.WeaponSelected;
			*pAdr->pLaraLocationFlags  =pRec->DatiLara.LaraLocationFlags;
			*pAdr->pAirAvailable  =pRec->DatiLara.AirAvailable;
			*pAdr->pVehicleIndex  =pRec->DatiLara.VehicleIndex;
			*pAdr->pWeaponHolding  =pRec->DatiLara.WeaponHolding;
			*pAdr->pPoison1  =pRec->DatiLara.Poison1;
			*pAdr->pPoison2  =pRec->DatiLara.Poison2;
			*pAdr->pFlagsLara  =pRec->DatiLara.FlagsLara;
			*pAdr->pFlagsLara2  =pRec->DatiLara.FlagsLara2;
			*pZonaSave_9d_CordYDaPeloAcqua = pRec->DatiLara.ZonaSave_9d_CordYDaPeloAcqua;

			// ripristinare tutto il blocco per orientamento lara
			for (i=0;i<14;i++) {
				pVetOrient[i] = pRec->DatiLara.VetBloccoOrient[i];
			}

			// reimpostare mesh
			i=GlobTomb4.pAdr->pVetSlot[0].IndexFirstMesh;
			BaseMeshLara = (DWORD) GlobTomb4.pAdr->VetMeshPointer[i];

			for (i=0;i<15;i++) {
				OffsetMesh = pRec->DatiLara.VetMeshLaraOffset[i] + BaseMeshLara;
				GlobTomb4.pAdr->VetMeshLara[i] = (StrMeshTr4*) OffsetMesh;
			}

			// ripristinare status di gocce su lara
			for (i=0;i<16;i++) {
				GlobTomb4.pAdr->pVetDrip[i] = pRec->DatiLara.VetDrip[i];
			}

			// indice item selezionato in inventario
			*pOggettoSelezionato = pRec->DatiLara.InventoryItemIndex;

			// impostare posizione di lara

			pLara = GlobTomb4.pAdr->pLara;

			AggiornaPositioneLara(pRec->DatiLara.Lara.CordX, pRec->DatiLara.Lara.CordY, pRec->DatiLara.Lara.CordZ, 
										pRec->DatiLara.Lara.Room , false);

			// ora copiare altri valori

			pLara->AnimationNow = pRec->DatiLara.Lara.AnimationNow;

			pLara->FlagsMain=pRec->DatiLara.Lara.FlagsMain;
			pLara->FlagsSwapMesh=pRec->DatiLara.Lara.FlagsSwapMesh;
			pLara->FrameNow=pRec->DatiLara.Lara.FrameNow;
			pLara->StateIdAI =pRec->DatiLara.Lara.StateIdAI ;
			pLara->IdSprite1=pRec->DatiLara.Lara.IdSprite1 ;
			pLara->IdSprite2=pRec->DatiLara.Lara.IdSprite2;
			pLara->MeshVisibilityMask=pRec->DatiLara.Lara.MeshVisibilityMask ;
			pLara->OrientationH=pRec->DatiLara.Lara.OrientationH;
			pLara->OrientationT=pRec->DatiLara.Lara.OrientationT;
			pLara->OrientationV=pRec->DatiLara.Lara.OrientationV;
			pLara->StateIdCurrent=pRec->DatiLara.Lara.StateIdCurrent;
			pLara->StateIdNext=pRec->DatiLara.Lara.StateIdNext;
			pLara->Trasparency=pRec->DatiLara.Lara.Trasparency;
			pLara->SpeedH=pRec->DatiLara.Lara.SpeedH ;
			pLara->SpeedV=pRec->DatiLara.Lara.SpeedV ;
			pLara->Health=pRec->DatiLara.Lara.Health ;
			// -------------------




		}
		for (i=0;i<255;i++) {
			GlobTomb4.pAdr->pVetInputKeyboard[i]=0;
		}

		GestioneComandiSpeech();
		if (pRec->IndexFrame >= pRec->TotFrames) {
			pRec->Status = RECF_STOP;
			TerminaAllSpeech();
			// analisi per fine demo
			if (GestioneDemoInProgress(FlagGDemo | FDG_END, pDemo)==1) {

				// chiamarlo di nuovo per impostare nuovo demo di stesso livello
				GestioneDemo(TestFakeUpdateInput);
				pRec->IndexFrame=0;
				break;
			
			}
		

		}else {

			// se questo demo sta venendo eseguito su lancio da title gestire stringa e altra roba
			GestioneDemoInProgress(FlagGDemo | FDG_IN_PROGRESS, pDemo);


			*GlobTomb4.pAdr->pInputExtGameCommands = DecodeGameCommand(pRec->VetFrames[pRec->IndexFrame++]);

			// vedere se si puo' interromprere con escape
			TestOkEscape=true;
		
			if (pDemo->TestDemoInProgress==true && (pDemo->Flags & DEMF_QUIT_WITH_ESCAPE)==0) TestOkEscape=false;
			
			if (TestOkEscape) {
				if (TastoVKPremuto(VK_ESCAPE)) {
					pRec->Status = RECF_STOP;
					TerminaAllSpeech();
					// attendere rilascio di escape
					while (TastoVKPremuto(VK_ESCAPE)) Sleep(0);

					GestioneDemoInProgress(FlagGDemo | FDG_END | FDG_END_FOR_ESCAPE, pDemo);


				}
			}
		}
	}

}
// gestione iniziale di S_UpdateInput
// usare valore globale 	mov eax, 535780h   ;InputExtGameCommands
// per sapere quali flag sono gia' stati premuti
// se restituisce true vuiol dire "aboetisci ibnput" ed esce da procedura
// se restituisce false continua normalmente
bool ControllaInput1(void)
{
	WORD StateId;
	int i;
	DWORD Mask;
	DWORD FlagsSkip;


	bool TestToglieAction;

	bool TestEsegui;
	int  Maschera;
	int n;
	StrGlobalTrigger *pGlobal;

	SimulaCrash();
	// se si sta registrando demo salvare tasto e frame attuale
	if (GlobTomb4.pBaseDemo->Status != RECF_STOP) GestioneDemo(false);
	

	// ontrollare per global trigger relativi a tasti o scancodes
	if (GlobTomb4.pBaseGlobalTriggers->TotTriggers) {
		pGlobal = &GlobTomb4.pBaseGlobalTriggers->VetTriggers[0];

		for (i=0;i<GlobTomb4.pBaseGlobalTriggers->TotTriggers;i++) {
			if ((pGlobal->Flags & FGT_DISABLED) == 0) {
				TestEsegui = false;

				switch (pGlobal->GlobalTrigger) {
				case GT_GAME_KEY1_COMMAND:
				case GT_GAME_KEY2_COMMAND:

					Mask= pGlobal->Parameter;

					if (pGlobal->GlobalTrigger == GT_GAME_KEY2_COMMAND) {
						Mask <<= 16;
					}

					if ((*GlobTomb4.pAdr->pInputExtGameCommands & Mask)== Mask) {
						// condizione vera
						// vedere se si deve verificare una altra condizione
						TestEsegui=true;
						if (pGlobal->IndiceConditionGroup != -1) {
							GlobTomb4.pMexLastTGCaller = "Condition TG for global trigger GT_GAME_KEY1/2 type";
							if (EseguiTriggerGroup(
									pGlobal->IndiceConditionGroup) == 0) TestEsegui=false;
						}


						if (TestEsegui) {
							
							
							// disabilitarlo se e' di tipo single shot
							if (pGlobal->Flags & FGT_SINGLE_SHOT) 
										pGlobal->Flags |= FGT_DISABLED;

							// se richiede rimozione del comando farlo subito
							if (pGlobal->Flags & FGT_REMOVE_INPUT) {
								*GlobTomb4.pAdr->pInputExtGameCommands &= ~Mask;
							}
							GlobTomb4.pMexLastTGCaller = "PerformTriggerGroup for global trigger GT_GAME_KEY1/2 type";
							EseguiTriggerGroup(pGlobal->IndicePerformGroup);

						}
					}
					break;
				case GT_KEYBOARD_CODE:
					if (GlobTomb4.pAdr->pVetInputKeyboard[pGlobal->Parameter]) {
						// vedere se si deve verificare una altra condizione
						TestEsegui=true;
						if (pGlobal->IndiceConditionGroup != -1) {
							GlobTomb4.pMexLastTGCaller = "Condition TG for global trigger GT_KEYBOARD_CODE type";
							if (EseguiTriggerGroup(
									pGlobal->IndiceConditionGroup) == 0) TestEsegui=false;
						}


						if (TestEsegui) {
							
							
							// disabilitarlo se e' di tipo single shot
							if (pGlobal->Flags & FGT_SINGLE_SHOT) 
										pGlobal->Flags |= FGT_DISABLED;

							// se richiede rimozione del comando farlo subito
							if (pGlobal->Flags & FGT_REMOVE_INPUT) {
								GlobTomb4.pAdr->pVetInputKeyboard[
												pGlobal->Parameter]=0;								
							}
							GlobTomb4.pMexLastTGCaller = "PerformTriggerGroup for global trigger GT_KEYBOARD_CODE type";
							EseguiTriggerGroup(pGlobal->IndicePerformGroup);

						}
					}
					break;
						
				}
			}
			
			pGlobal++;
		}

	}

	// se siamo in flyby o title disabilitare tasti numerici
	FlagsSkip= FindSkipPhase();

	if ((FlagsSkip & (SKIP_FLY_CAMERA | SKIP_GRAY_SCREEN | SKIP_TITLE_LEVEL)) ||
			(GlobTomb4.StatusNG & SNG_DISABLE_WEAPONS)) {

		if (GlobTomb4.StatusNG & SNG_DISABLE_WEAPONS) 
			n=7;
		else
			n=11;

		// disattivare tutti i tasti numerici
		for (i=2;i<=n;i++) {
			GlobTomb4.pAdr->pVetInputKeyboard[i]=0;
		}
	}

	// se siamo in modo binocolo ed e' stato premuto inventario togliere binocolo
	if ((FlagsSkip & SKIP_BINOCULARS) && (*GlobTomb4.pAdr->pInputExtGameCommands & 0x100)) {
		*GlobTomb4.pAdr->pZoomFactor =0;
		*GlobTomb4.pAdr->pInputExtGameCommands &= ~0x100;
		*GlobTomb4.pAdr->pInputGameCommands &= ~0x100;
		*GlobTomb4.pAdr->pInputCommandFlags &= ~0x100;
		GlobTomb4.pAdr->pVetInputKeyboard[1]=0;	
		*GlobTomb4.pAdr->pFlagsLara2 &= ~0x10;
		*GlobTomb4.pAdr->pTurnHLaraHeadEnd =0;
		*GlobTomb4.pAdr->pTurnVLaraHeadEnd =0;
		*GlobTomb4.pAdr->pTurnHLaraHeadNow =0;
		*GlobTomb4.pAdr->pTurnVLaraHeadNow =0;
		AlterFOV(0x38e0);
		*GlobTomb4.pAdr->pFlashDurate=0;
		GlobTomb4.pAdr->pLara->MeshVisibilityMask = -1;
		
	}
	// stessa cosa per tasto pausa
	if ((FlagsSkip & SKIP_BINOCULARS) && (*GlobTomb4.pAdr->pInputExtGameCommands & 0x2000)) {
		*GlobTomb4.pAdr->pZoomFactor =0;
		*GlobTomb4.pAdr->pInputExtGameCommands &= ~0x2000;
		*GlobTomb4.pAdr->pInputGameCommands &= ~0x2000;
		*GlobTomb4.pAdr->pInputCommandFlags &= ~0x2000;
		GlobTomb4.pAdr->pVetInputKeyboard[25]=0;	
		*GlobTomb4.pAdr->pFlagsLara2 &= ~0x10;
		*GlobTomb4.pAdr->pTurnHLaraHeadEnd =0;
		*GlobTomb4.pAdr->pTurnVLaraHeadEnd =0;
		*GlobTomb4.pAdr->pTurnHLaraHeadNow =0;
		*GlobTomb4.pAdr->pTurnVLaraHeadNow =0;
		AlterFOV(0x38e0);
		*GlobTomb4.pAdr->pFlashDurate=0;
		GlobTomb4.pAdr->pLara->MeshVisibilityMask = -1;
		
	}

	// qui fare controlli per tasti escape  e pausa
	// e anche per fine mirino quando prima c'era e togliere il colore subito
	if ((FlagsSkip & SKIP_LASER_SIGHT) && (*GlobTomb4.pAdr->pInputExtGameCommands & 0x100)) {
		// premuto inventario mentre c'e' mirino laser.
		// uhm pero' mica facile
		*GlobTomb4.pAdr->pInputExtGameCommands &= ~0x100;
		*GlobTomb4.pAdr->pInputGameCommands &= ~0x100;
		GlobTomb4.pAdr->pVetInputKeyboard[1]=0;	

	}

	// ora per pausa
	if ((FlagsSkip & SKIP_LASER_SIGHT) && (*GlobTomb4.pAdr->pInputExtGameCommands & 0x2000)) {

		*GlobTomb4.pAdr->pInputExtGameCommands &= ~0x2000;
		*GlobTomb4.pAdr->pInputGameCommands &= ~0x2000;
		GlobTomb4.pAdr->pVetInputKeyboard[25]=0;	

		
	}
	// con laser sight disattivare cambio di armi (vedere se funziona)
	if (FlagsSkip & SKIP_LASER_SIGHT) {
		for (i=1;i<12;i++) {
			GlobTomb4.pAdr->pVetInputKeyboard[i]=0;

		}
	}
	// se prima c'era lasersight e ora non c'e' piu' ed era attivo flag per colorare lo schermo
	// disattivarlo subito
	if ((FlagsSkip & SKIP_LASER_SIGHT)==0 && GlobTomb4.TestOldLaserSight == true && *GlobTomb4.pAdr->pFlashDurate !=0) {
		*GlobTomb4.pAdr->pFlashDurate=0;
	}

	if ((FlagsSkip & SKIP_BINOCULARS)==0 && GlobTomb4.TestOldBinoculars == true) {
		*GlobTomb4.pAdr->pFlashDurate=0;
		GlobTomb4.TestOldBinoculars=false;
	}

	// disattivare solo armi se c'e' un veicolo attivo
	if (*GlobTomb4.pAdr->pVehicleIndex != -1) {
		for (i=0;i<6;i++) {
			GlobTomb4.pAdr->pVetInputKeyboard[i+2]=0;
		}
	}


	// vedere se c'e' da disdabilitare tasto per guardare
	if (GlobTomb4.TestDisableFeatures & DF_GUARDA) {
		if (*GlobTomb4.pAdr->pInputExtGameCommands & 0x200) {
			*GlobTomb4.pAdr->pInputExtGameCommands =0;
		}

	}

	// bloccare tasto azione se siamo in modalita' hang
	// o tira su ecc
	// e c'' il divieto di hang su uel bordo
	if (GlobTomb4.HangForbidden) {
		

		StateId = GlobTomb4.pAdr->pLara->StateIdCurrent;
		// c'era 29
		if (StateId == 10 || StateId == 11 || StateId==28 ||  
			StateId==96  || StateId==19 || StateId==30 || StateId == 31) {
			TestToglieAction = IsHangVietato();


			if (TestToglieAction) {
				// togleire action
				*GlobTomb4.pAdr->pInputExtGameCommands &= ~0x40;


			}
			
			
		}
	}

	// se c'e' patch per arpione subacueso attivo e lara e' sottacqua
	// o galleggiante e lara ha in mano balestra
	// schermare tasto salto (0x10)
	if (GlobTomb4.pBaseCustomize->BaseHarpoon.TestArpione== true &&
		(GlobTomb4.pBaseCustomize->BaseHarpoon.ArpioneFlags & HRP_NO_SWIM_UNDERWATER)!= 0) {

		i = *GlobTomb4.pAdr->pLaraLocationFlags;
		if (i == 1 || i == 2) {
			// lara e' sottacqua o galleggiante
			// ora vedere se lara ha in mano balestra
			if (IsLaraHolding(HOLD_CROSSBOW)==true) {
				// ok,disattivare il salto
				*GlobTomb4.pAdr->pInputExtGameCommands &= ~0x10;
				GlobTomb4.pAdr->pVetInputKeyboard[56] =0;
			}
		}
		
	}


	// se e' attivo blocco cammina avanti davanti a fossato dummy
	// disattivare il tasto avanti
	if (GlobTomb4.TestDummyBlockForward) {
		if ((*GlobTomb4.pAdr->pInputExtGameCommands & 0x81)== 0x81) {
			// e' ancora attivo: togliere tasto avanti
			*GlobTomb4.pAdr->pInputExtGameCommands &= ~0x01;
			GlobTomb4.pAdr->pVetInputKeyboard[72] =0;
		}else {
			// disattivare il blocco in avanti
			GlobTomb4.TestDummyBlockForward =false;
		}
	}
	// se c'e' maschera di blocco pulsanti applicarla
	// ma se non ci fosse azzerare i tasti stoppati
	GlobTomb4.KeysStopped =0;

	if (GlobTomb4.KeysToStop) {
		Maschera = GlobTomb4.KeysToStop;
		GlobTomb4.KeysStopped = *GlobTomb4.pAdr->pInputExtGameCommands;

		if (Maschera == CMD_ALL) {
			// controllare per eventuale cattura schermo
			Patch_CA();
			// disattiva tutto
			// se pero c'e' keypad attivo, salva lo statu
			// questo farlo sempre

			memcpy(GlobTomb4.VetKeysToStop, 
					GlobTomb4.pAdr->pVetInputKeyboard , 256);
			
			ImpostaTempoUltimoComando();
			memset(GlobTomb4.pAdr->pVetInputKeyboard ,0,256);
			*GlobTomb4.pAdr->pInputExtGameCommands = 0;
			// se c'e filmato in corso  abortire del tutto il direct input
			//if (GlobTomb4.BaseFMV.TestFMVInCorso==true) return true;

			
		}else {


			// prima analizzare codici speciali
			if (Maschera & CMD_SAVE_GAME) {
				
				GlobTomb4.pAdr->pVetInputKeyboard[0x3f] = 0;


			}

			if (Maschera & CMD_LOAD_GAME) {
				// togliere tasto f6
				GlobTomb4.pAdr->pVetInputKeyboard[0x40] = 0;

			}

			if (Maschera & CMD_WEAPON_KEYS) {
				// togliere tasti di selezione rapida arma
				// osia tasti che vanno da "1" a "6"
				for (i =0;i<6;i++) {
					GlobTomb4.pAdr->pVetInputKeyboard[2+i] = 0;
				}
				// ora togleire da maschera questo flag perche' e' irregolare
				Maschera &= ~CMD_WEAPON_KEYS;
			}
			if (Maschera & CMD_ACTION) {
				// se c'e' action aggiungere anche ENTER come tasto da eliminare
				Maschera |= 0x100000;
			}

			// ok ora eliminare valori
			*GlobTomb4.pAdr->pInputExtGameCommands &= ~Maschera;
		}
	}

	if (GlobTomb4.KeySingleToSend != 0) {
		// inviare solo per una volta questo tasto e poi azzerare
		GlobTomb4.pAdr->pInputExtGameCommands[0] |= GlobTomb4.KeySingleToSend;
		GlobTomb4.KeySingleToSend=0;


	}
	if (GlobTomb4.KeysToSend) {
		Maschera = GlobTomb4.KeysToSend;

		if (Maschera != CMD_ALL) {
			// prima analizzare codici speciali
			if (Maschera & CMD_SAVE_GAME) {
				// qui ci sarebbe molto da fare, ma per ora attivare
				// solo tasto F5
				GlobTomb4.pAdr->pVetInputKeyboard[0x3f] = 1;
#ifdef DEBUG_ON
				InviaLog("Invio simulato tasto F5");
#endif
			}

			if (Maschera & CMD_LOAD_GAME) {
				// aggiungere tasto f6
				GlobTomb4.pAdr->pVetInputKeyboard[0x40] = 1;
			}

			if (Maschera & CMD_WEAPON_KEYS) {
				// aggiungere tasti di selezione rapida arma
				// osia tasti che vanno da "1" a "6"
				for (i =0;i<6;i++) {
					GlobTomb4.pAdr->pVetInputKeyboard[2+i] = 1;
				}
				// ora togleire da maschera questo flag perche' e' irregolare
				Maschera &= ~CMD_WEAPON_KEYS;
			}

			GlobTomb4.pAdr->pInputExtGameCommands[0] |= Maschera;
					
		
		}

	}
	if (*GlobTomb4.pAdr->pInputExtGameCommands != 0) {
		ImpostaTempoUltimoComando();
	}




	return false;
	

}


bool ScopreModoFullScreen(void)
{
	BYTE **p2_BaseGlobale = (BYTE **) 0x754468;
	BYTE *pBaseGlobale;

	pBaseGlobale = *p2_BaseGlobale;

	if (pBaseGlobale==NULL) return false;

	if (pBaseGlobale[0x4c] & 0x02)  return false;
	return true;

}
// restituisce true se almeno un tasto della tastiera e' premuto
bool IsTastiDown(void)
{
	int i;

	for (i=VK_BACK;i<VK_F13;i++) {
		switch (i) {
			// tasti da ignorare
		case 0x09:
		case 0x0a:
		case VK_CAPITAL:

		case 0x15:
		case 0x16:
		case 0x17:
		case 0x18:
		case 0x19:
		case 0x1a:

		case 0x1c:
		case 0x1d:
		case 0x1e:
		case 0x1f:

		case 0x2a:
		case 0x2b:
		case 0x2c:

		case 0x3a:
		case 0x3b:
		case 0x3c:
		case 0x3d:
		case 0x3e:
		case 0x3f:

		case 0x5b:
		case 0x5c:
		case 0x5d:
		case 0x5e:
		case 0x5f:

			break;
		default:
			if (GetAsyncKeyState(i)) {
				/*
				sprintf(BufferLog,"\tPremuto VK=0x%X", i);
				InviaLog(BufferLog);
				*/
				return true;
			}
		}
	}

				
	return false;

}




void LogPer3dPrincipale(void)
{
	static DWORD *pDirect3d_Principale = (DWORD *) 0x7538B9;

	sprintf(BufferLog,"Valore pDirect3d_Principale=0x%X", *pDirect3d_Principale);
	InviaLog(BufferLog);

}
// viene chiamata ogni volta che c'e' un messaggio inviato 
// a window procedure di tomb4
// se restituisce 1 allora il messaggio andra' inviato alla vera
// windowprocedure
// se restituisce 0, il messaggio viene inviato a defwindowprocedure 
// come se fosse stato ignorato.
// se si restituisce 0x8000 0000 (se c'e' bit segno) allora si deve 
// restituire il valore con and 0x7ffffff e tornare subito

// possibili valori da restituire
// #define RET_ABORT_FALSE 0x80000000
// #define RET_ABORT_TRUE  0x80000001
// #define RET_DEF_WINDOWPROC 0x0
// #define RET_CONTINUE 0x1
int RedirWindowProcedure(HWND hWindow, UINT uMsg, WPARAM wParam, LPARAM lParam)
{

	BYTE *pTestCloseWindow = (BYTE*) 0x753B8C;
	BYTE *pTestFMVAttivo = (BYTE*) 0x753947;
	BYTE *pTestGameAttivo = (BYTE*) 0x753935;
	int *pTestBeginScene = (int*) 0x753915;
	int *pTestStopGame = (int*) 0x753919;	
	BYTE *pFlagWindow = (BYTE*) 0x7538FD;


//	WINDOWPOS *pPos;


	// DWORD TempoStart;

	static HINSTANCE *pTombInstance = (HINSTANCE*) 0x753858;

	

	if (GlobTomb4.BaseFMV.TestIgnoraTutto) {
		if (GlobTomb4.BaseFMV.TestFullScreen) return RET_DEF_WINDOWPROC;
		// se modo windowed invece abort
		return RET_ABORT_TRUE;
	}


	if (GlobTomb4.TestDebuggerInProgress) {
		// se debugger e' attivo, ignorare messaggi windows per stop task
		if (uMsg == WM_ACTIVATE)  return RET_ABORT_TRUE;
	}


	return RET_CONTINUE;

}



// converte coordinata float di game engine tomb4 in valore pixel
// (questo funziona quantomeno per dimensione texture e posizione)
int FloatCord2Int(float Cord)
{
	float Temp;

	Temp = 256 * Cord;
	return (int) Temp;

}

// funzione inversa alla precedente: trasforma un valore intero in pixel
// nel corrispondente valore float nella forma n/256
float IntCord2Float(int Cord)
{
	float Temp;

	Temp = ((float) Cord) / 256;

	return Temp;
}
